import { batch, useDispatch, useStore } from 'react-redux';
import { useNavigate } from 'react-router-dom';

import { notesActions, selectNotes } from 'app/services/NotesService';
import { selectSettings, settingsActions } from 'app/services/SettingsService';
import type { RootState } from 'app/services/types';

import { activeSavedTrack } from './savedMelodies';
import { melodiesActions } from './slice';
import { selectSavedMelodies } from './slice/selectors';
import type { Melody } from './types';
import { getMelodyBpm } from './useCurrentMelody';

export const useOpenMelodyInStudio = (stopPlayback: () => void) => {
  const store = useStore<RootState>();
  const dispatch = useDispatch();
  const navigate = useNavigate();

  return (melody: Melody) => {
    const state = store.getState();
    const recording = selectNotes(state);
    const saved = selectSavedMelodies(state).find(
      item => item.id === melody.title,
    );
    if (selectSettings(state).isRecording) return;
    if (
      (recording.melody.notes.length || recording.project) &&
      !window.confirm(
        'Replace the current composition in Melody Studio? Any unsaved changes will be lost.',
      )
    )
      return;

    stopPlayback();
    const activeTrack = saved && activeSavedTrack(saved);
    const active = activeTrack
      ? {
          ...melody,
          title: activeTrack.melody.title,
          displayTitle: activeTrack.melody.displayTitle,
        }
      : melody;
    batch(() => {
      if (saved) {
        dispatch(
          notesActions.loadRecordingProject({
            title: saved.name,
            activeTrackId: saved.activeTrackId,
            tracks: saved.tracks.map(track =>
              track.id === saved.activeTrackId
                ? { ...track, melody: active }
                : track,
            ),
            savedMelodyId: saved.id,
          }),
        );
      } else {
        dispatch(notesActions.loadRecording(melody));
      }
      dispatch(
        settingsActions.loadMelodySettings({
          ...active,
          bpm: getMelodyBpm(active),
        }),
      );
      dispatch(melodiesActions.rememberMelodyOpened(melody.title));
    });
    navigate('/sandbox/editor');
  };
};
