import { useCallback, useEffect, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import {
  loadAudioRouting,
  saveAudioRouting,
} from 'app/services/AudioRoutingService/preferences';
import { selectEffects } from 'app/services/EffectsService/selectors';
import {
  LIVE_INPUT_EFFECTS_KEY,
  defaultEffects,
  maxEffectsVolume,
  mixerEffectNames,
} from 'app/services/EffectsService/settings';
import { effectsActions } from 'app/services/EffectsService/slice';
import { useGuitarInput } from 'app/services/GuitarInputService/useGuitarInput';
import { selectSettings } from 'app/services/SettingsService';

import { EffectMixer, PowerIcon } from './EffectMixer';
import { EffectPresets } from './EffectPresets';
import { EffectsRouting } from './EffectsRouting';
import { HeaderIcon } from './HeaderIcon';
import { HeaderIconButton } from './HeaderIconControl';
import { HeaderPopup, useHeaderPopupDismiss } from './HeaderPopup';

export const InstrumentEffects = ({
  guitar,
  open: controlledOpen,
  onOpenChange,
  inline = false,
}: {
  guitar: ReturnType<typeof useGuitarInput>;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  inline?: boolean;
}) => {
  const dispatch = useDispatch();
  const { timbre, isRecording } = useSelector(selectSettings);
  const [live, setLive] = useState(() => loadAudioRouting().live);
  const liveEffects = live && (guitar.inputSound ?? 'effects') === 'effects';
  const effectsKey = liveEffects ? LIVE_INPUT_EFFECTS_KEY : timbre;
  const { instruments } = useSelector(selectEffects);
  const settings = instruments[effectsKey] ?? defaultEffects(effectsKey);
  const [localOpen, setLocalOpen] = useState(false);
  const open = controlledOpen ?? localOpen;
  const setOpen = useCallback(
    (next: boolean) => (onOpenChange ?? setLocalOpen)(next),
    [onOpenChange],
  );
  const trigger = useRef<HTMLButtonElement>(null);
  const closeButton = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLElement>(null);
  const close = () => {
    setOpen(false);
    trigger.current?.focus();
  };

  useHeaderPopupDismiss(open, setOpen, trigger, panel);

  useEffect(() => {
    if (!open) return;
    closeButton.current?.focus();
  }, [open, setOpen]);

  const update = (next: typeof settings) => {
    if (liveEffects) guitar.updateLiveEffects(next);
    else dispatch(effectsActions.setInstrument({ timbre, settings: next }));
  };
  const activeCount = mixerEffectNames.filter(
    name => settings[name].enabled,
  ).length;
  const activePedals = (settings.pedals ?? []).filter(
    pedal => pedal.enabled,
  ).length;

  return (
    <>
      {!inline && (
        <Trigger
          ref={trigger}
          type="button"
          aria-expanded={open}
          aria-controls="instrument-effects"
          aria-haspopup="dialog"
          aria-label="Effects"
          title={`Effects${activeCount > 0 ? `: enabled ${activeCount}` : ''}${
            activePedals > 0 ? `. Pedals: ${activePedals}` : ''
          }${settings.bypass ? '. Bypass is on' : ''}`}
          data-active={
            (activeCount > 0 || activePedals > 0) && !settings.bypass
          }
          onClick={() => (open ? close() : setOpen(true))}
        >
          <HeaderIcon name="effects" />
        </Trigger>
      )}
      {(open || inline) && (
        <Panel
          $inline={inline}
          $width={1240}
          ref={panel}
          id={inline ? undefined : 'instrument-effects'}
          role={inline ? undefined : 'dialog'}
          aria-label="Instrument effects"
        >
          <Toolbar>
            <BypassButton
              type="button"
              aria-label="Bypass all effects"
              title="Temporarily disables processing while preserving effect settings."
              aria-pressed={settings.bypass}
              onClick={() => update({ ...settings, bypass: !settings.bypass })}
            >
              <PowerIcon />
              Bypass
            </BypassButton>
            <ChainStatus role="status" aria-label="Chain status">
              {settings.bypass
                ? 'Unprocessed'
                : `Enabled effects: ${activeCount} / ${
                    mixerEffectNames.length
                  }${
                    settings.pedals?.length
                      ? ` · Pedals: ${activePedals} / ${settings.pedals.length}`
                      : ''
                  }`}
            </ChainStatus>
            <ResetButton
              type="button"
              onClick={() => update(defaultEffects(effectsKey))}
            >
              Reset settings
            </ResetButton>
            {!inline && (
              <CloseButton
                ref={closeButton}
                type="button"
                onClick={close}
                aria-label="Close effects"
              >
                <span aria-hidden="true">×</span>
              </CloseButton>
            )}
          </Toolbar>
          <EffectsRouting
            guitar={guitar}
            live={live}
            onLiveChange={value => {
              setLive(value);
              saveAudioRouting({ live: value });
            }}
            recording={isRecording}
          />
          <EffectPresets key={effectsKey} settings={settings} onChange={update}>
            <EffectMixer
              stage={settings}
              onChange={stage => update({ ...settings, ...stage })}
              bypassed={settings.bypass}
              output={{
                label: liveEffects ? 'Audio input volume' : 'Instrument volume',
                value: settings.volume,
                max: maxEffectsVolume(effectsKey),
                onChange: volume => update({ ...settings, volume }),
              }}
            />
          </EffectPresets>
        </Panel>
      )}
    </>
  );
};

const Trigger = styled(HeaderIconButton)``;

const Panel = styled(HeaderPopup)`
  padding: 16px;
  button,
  input {
    font: inherit;
  }
  button {
    cursor: pointer;
  }
  :focus-visible,
  button:focus-visible {
    outline: 2px solid ${p => p.theme.primary};
    outline-offset: -2px;
  }
  @media (max-width: 480px) {
    padding: 12px;
  }
`;

const Toolbar = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 12px;
  margin-bottom: 16px;
`;

const Button = styled.button`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 36px;
  padding: 6px 10px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 6px;
  color: ${p => p.theme.textSecondary};
  background: ${p => p.theme.surface};
  font-size: 12px !important;
  &:hover {
    color: ${p => p.theme.text};
    background: ${p => p.theme.backgroundVariant};
  }
`;

const BypassButton = styled(Button)`
  &[aria-pressed='true'] {
    color: ${p => p.theme.warning};
    background: ${p => p.theme.warningBackground};
    border-color: currentColor;
  }
`;

const ChainStatus = styled.span`
  flex: 1;
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
  @media (max-width: 480px) {
    order: 4;
    flex-basis: 100%;
  }
`;

const ResetButton = styled(Button)`
  margin-left: auto;
`;

const CloseButton = styled(Button)`
  width: 36px;
  padding: 0;
  font-size: 24px !important;
`;
