import { getNoteDuration } from 'app/services/MelodiesService/timing';
import { Melody } from 'app/services/MelodiesService/types';

const MAX_ONSETS = 8;
const PHRASE_REST = 1000;

export const getPracticePhrases = (notes: Melody['notes']) => {
  const phrases: { start: number; notes: Melody['notes'] }[] = [];
  let previousStart = -Infinity;
  let end = 0;
  let onsets = 0;
  [...notes]
    .sort((a, b) => a.start - b.start)
    .forEach(note => {
      if (note.start !== previousStart) {
        if (
          !onsets ||
          onsets === MAX_ONSETS ||
          note.start - end >= PHRASE_REST
        ) {
          phrases.push({ start: note.start, notes: [] });
          onsets = 0;
          end = note.start;
        }
        onsets++;
        previousStart = note.start;
      }
      phrases[phrases.length - 1].notes.push(note);
      end = Math.max(end, note.start + getNoteDuration(note));
    });
  return phrases;
};
