import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { splitNote } from 'app/services/NotesService/noteUtils';
import { selectSettings } from 'app/services/SettingsService';
import { fixedNotesFor } from 'app/services/SynthesizerService/timbres';

import { PianoOctave } from './PianoOctave';

export const Piano = () => {
  const { timbre } = useSelector(selectSettings);
  const fixedNotes = fixedNotesFor(timbre);
  const octaves = fixedNotes
    ? Array.from(new Set(fixedNotes.map(note => splitNote(note)[1])))
    : [1, 2, 3, 4, 5, 6, 7];
  return (
    <PianoWrapper>
      {octaves.map(octave => (
        <PianoOctave key={`piano-octave-${octave}`} octave={octave} />
      ))}
    </PianoWrapper>
  );
};

const PianoWrapper = styled.div`
  display: inline-flex;
  flex-direction: row;
`;
