import { useMemo } from 'react';
import styled from 'styled-components';

import { getBeatsPerMeasure } from 'app/services/MelodiesService/meter';
import { MAX_TEMPO, MIN_TEMPO } from 'app/services/MelodiesService/tempo';
import {
  PhraseNote,
  composePhrase,
} from 'app/services/MelodyGenerationService/compose';
import {
  GenerationSettings,
  MAX_BARS,
  MIN_BARS,
  STEPS_PER_BEAT,
} from 'app/services/MelodyGenerationService/options';
import { getMeterBeats } from 'app/services/MetronomeService/rhythm';

const width = 400;
const melodyHeight = 146;
const trackHeight = 36;

export const MelodyGeneratorPreview = ({
  settings,
}: {
  settings: GenerationSettings;
}) => {
  const example = useMemo(
    () => composePhrase({ ...settings, bars: 4 }, () => 0),
    [settings],
  );
  const quarterNotes = getBeatsPerMeasure(settings.timeSignature);
  const barSteps = quarterNotes * STEPS_PER_BEAT;
  const secondsPerBar = (quarterNotes * 60) / settings.bpm;
  const duration = Math.round(secondsPerBar * settings.bars);
  const validTempo =
    Number.isInteger(settings.bpm) &&
    settings.bpm >= MIN_TEMPO &&
    settings.bpm <= MAX_TEMPO;
  const showDuration =
    validTempo &&
    Number.isInteger(settings.bars) &&
    settings.bars >= MIN_BARS &&
    settings.bars <= MAX_BARS;
  const beats = getMeterBeats(settings.timeSignature);
  const tracks = [
    { label: 'Melody', notes: example.melody },
    { label: 'Chords', notes: example.accompaniment },
    { label: 'Bass', notes: example.bassNotes },
    { label: 'Drums', notes: example.drumNotes },
  ];
  const x = (step: number) => (step * width) / (2 * barSteps);

  return (
    <>
      <PreviewHeading>
        <h2>Pattern preview</h2>
        <p>Two example bars from your current settings.</p>
      </PreviewHeading>
      <Timeline>
        <span />
        <div>
          {[0, 1].map(bar => (
            <span key={bar}>
              Bar {bar + 1}
              {validTempo && (
                <small>{(bar * secondsPerBar).toFixed(1)} s</small>
              )}
            </span>
          ))}
        </div>
      </Timeline>
      <Tracks>
        <TrackLabels>
          {tracks.map(({ label, notes }) => (
            <li key={label}>
              {label}
              {!notes.length && <small>Off</small>}
            </li>
          ))}
        </TrackLabels>
        <Plot
          viewBox={`0 0 ${width} ${melodyHeight + 3 * trackHeight}`}
          preserveAspectRatio="none"
          aria-hidden="true"
        >
          {[0, 1].flatMap(bar =>
            beats.map(({ accent }, i) => {
              const tick = (bar * width) / 2 + (i * width) / (2 * beats.length);
              return (
                <line
                  key={tick}
                  x1={tick}
                  x2={tick}
                  y1="0"
                  y2="100%"
                  className={accent ? 'accent' : undefined}
                  vectorEffect="non-scaling-stroke"
                />
              );
            }),
          )}
          {tracks.map(({ label, notes }, row) => {
            const top = row ? melodyHeight + (row - 1) * trackHeight : 0;
            const height = row ? trackHeight : melodyHeight;
            const shown = notes.filter(note => note.start < 2 * barSteps);
            return (
              <g key={label} className={row ? 'backing' : 'lead'}>
                {row > 0 && (
                  <line
                    x1="0"
                    x2={width}
                    y1={top}
                    y2={top}
                    className="accent"
                  />
                )}
                {plotNotes(shown, x, top, height)}
              </g>
            );
          })}
        </Plot>
      </Tracks>
      <PreviewCaption>
        <span>Higher notes sit higher. Longer blocks hold longer.</span>
        {showDuration && (
          <strong>
            {settings.bars} bars · about {duration} sec
          </strong>
        )}
      </PreviewCaption>
    </>
  );
};

const plotNotes = (
  notes: PhraseNote[],
  x: (step: number) => number,
  top: number,
  height: number,
) => {
  if (!notes.length) return null;
  const pitches = notes.map(note => note.midi);
  const low = Math.min(...pitches);
  const high = Math.max(...pitches);
  const range = Math.max(high - low, 5);
  const middle = (high + low) / 2;
  const noteHeight = height > trackHeight ? 7 : 4;
  return notes.map(({ midi, start, length }) => (
    <rect
      key={`${start}-${midi}`}
      x={x(start) + 1}
      y={
        top +
        (height - noteHeight) / 2 -
        ((midi - middle) / range) * (height - noteHeight - 10)
      }
      width={Math.max(1, x(length) - 2)}
      height={noteHeight}
      rx="2"
    />
  ));
};

const PreviewHeading = styled.header`
  display: grid;
  gap: 4px;
`;

const Timeline = styled.div`
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  color: ${p => p.theme.textSecondary};
  font-size: 12px;
  font-weight: 650;
  margin-top: 4px;

  div {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  div > span {
    padding-left: 8px;
  }

  small {
    margin-left: 6px;
    font-size: inherit;
    font-weight: 400;
    font-variant-numeric: tabular-nums;
  }
`;

const Tracks = styled.div`
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.background};
`;

const TrackLabels = styled.ul`
  display: grid;
  grid-template-rows: ${melodyHeight}px repeat(3, ${trackHeight}px);
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 12px;
  font-weight: 650;

  li {
    display: grid;
    align-content: center;
    padding: 0 8px;
    background: ${p => p.theme.surface};
  }

  li + li {
    border-top: 1px solid ${p => p.theme.border};
  }

  small {
    color: ${p => p.theme.textSecondary};
    font-weight: 400;
    line-height: 1;
  }
`;

const Plot = styled.svg`
  display: block;
  width: 100%;
  height: ${melodyHeight + 3 * trackHeight}px;

  line {
    stroke: ${p => p.theme.practice.grid};
  }

  .accent {
    stroke: ${p => p.theme.border};
  }

  .lead {
    fill: ${p => p.theme.primary};
  }

  .backing {
    fill: ${p => p.theme.textSecondary};
  }
`;

const PreviewCaption = styled.div`
  display: grid;
  gap: 4px;
  color: ${p => p.theme.textSecondary};
  font-size: 13px;

  strong {
    color: ${p => p.theme.text};
    font-variant-numeric: tabular-nums;
  }
`;
