type Rhythm = {
  melody: [number[], number[]];
  backing: number[];
  brokenChord: boolean;
};

// Define onsets in beats and use a grid that fits halves, quarters and thirds.
const rhythm = (
  first: number[],
  second: number[],
  backing: number[],
  brokenChord = false,
): Rhythm => {
  const steps = (beats: number[]) =>
    beats.map(beat => Math.round(beat * STEPS_PER_BEAT));
  return {
    melody: [steps(first), steps(second)],
    backing: steps(backing),
    brokenChord,
  };
};

