const pick = <T>(choices: readonly T[], random: () => number) =>
  choices[Math.floor(random() * choices.length)];
const pickKey = <T extends object>(choices: T, random: () => number) =>
  pick(Object.keys(choices) as (keyof T)[], random);
const presetScales = (Object.keys(scales) as Scale[]).filter(
  value => value !== 'custom',
);

export const randomTiming = (random = Math.random) => ({
  bpm: MIN_TEMPO + Math.floor(random() * (MAX_TEMPO - MIN_TEMPO + 1)),
  bars: pick([4, 8, 12, 16, 24, 32], random),
  timeSignature: pick(TIME_SIGNATURES, random),
});

export const randomKey = (random = Math.random) => {
  const scale = pick(presetScales, random);
  return {
    tonic: pick(tonics, random),
    scale,
    mode: pick(scales[scale].modes as readonly Mode[], random),
  };
};

export const randomMelody = (random = Math.random) => ({
  timbre: pickKey(timbrePrograms, random),
  rhythm: pickKey(rhythms, random),
  mood: pickKey(moods, random),
});

export const randomAccompaniment = (random = Math.random) => ({
  chordPattern: pickKey(chordPatterns, random),
  bass: random() < 0.5,
  drums: random() < 0.5,
});
