import { useEffect, useRef, useState } from 'react';
import { useSelector, useStore } from 'react-redux';
import { Link } from 'react-router-dom';
import styled, { css } from 'styled-components';

import {
  getMelodyDuration,
  melodiesActions,
  selectMelodies,
  selectRecentLibraryMelodies,
} from 'app/services/MelodiesService';
import { useLibraryPlayback } from 'app/services/MelodiesService/useLibraryPlayback';
import { useOpenMelodyInStudio } from 'app/services/MelodiesService/useOpenMelodyInStudio';
import { guitarExercises } from 'app/services/PlayAlongService/guitarExercises';
import { selectSettings } from 'app/services/SettingsService';
import type { RootState } from 'app/services/types';

import { HeaderIcon } from 'app/components/HeaderIcon';
import {
  MelodyActionButton,
  MelodyActionIcon,
} from 'app/components/MelodyAction';
import { MelodyEditorIcon } from 'app/components/MelodyEditorAction';
import { MelodyImport } from 'app/components/MelodyImport';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

const normalizeSearch = (text: string) =>
  text.normalize('NFKC').toLowerCase().replace(/ё/g, 'е');

export const MelodiesListPage = () => {
  const [query, setQuery] = useState('');
  const [failedDeletion, setFailedDeletion] = useState<string | null>(null);
  const searchInput = useRef<HTMLInputElement>(null);
  const store = useStore<RootState>();
  const playback = useLibraryPlayback();
  const openInStudio = useOpenMelodyInStudio(playback.stop);
  const { isRecording } = useSelector(selectSettings);
  const { libraryEdits, savedMelodies } = useSelector(selectMelodies);
  const savedIds = new Set(savedMelodies.map(melody => melody.id));
  const playableMelodies = useSelector(selectRecentLibraryMelodies).filter(
    melody =>
      getMelodyDuration(melody) ||
      libraryEdits[melody.title] ||
      savedIds.has(melody.title),
  );
  const terms = normalizeSearch(query).trim().split(/\s+/).filter(Boolean);
  const matchingMelodies = playableMelodies.filter(melody => {
    const text = normalizeSearch(
      [
        melody.displayTitle,
        !savedIds.has(melody.title) && melody.title,
        melody.author,
      ]
        .filter(Boolean)
        .join(' '),
    );
    return terms.every(term => text.includes(term));
  });
  const activeVisible = matchingMelodies.some(
    melody => melody.title === playback.activeTitle,
  );
  const { activeTitle, stop } = playback;

  useEffect(() => {
    if (activeTitle && !activeVisible) stop();
  }, [activeTitle, activeVisible, stop]);

  const deleteMelody = (id: string, title: string) => {
    if (!window.confirm(`Delete "${title}" from Melodies?`)) return;
    store.dispatch(melodiesActions.deleteSavedMelody(id));
    const { savedMelodySaveError } = selectMelodies(store.getState());
    setFailedDeletion(savedMelodySaveError ? title : null);
    if (!savedMelodySaveError) searchInput.current?.focus();
  };

  return (
    <Library as="main" aria-label="Melodies">
      <LibraryActions>
        <MelodyImport onBeforeOpen={playback.stop} />
        <MelodyActionButton as={Link} $withLabel to="/generate-melody">
          Generate melody
        </MelodyActionButton>
      </LibraryActions>
      <ExerciseSection aria-labelledby="guitar-exercises-heading">
        <h2 id="guitar-exercises-heading">Guitar exercises</h2>
        <ExerciseList role="list">
          {guitarExercises.map(({ melody }, index) => (
            <li key={melody.title}>
              <ExerciseLink
                to={`/guitar-practice-routine?exercise=${encodeURIComponent(
                  melody.title,
                )}`}
              >
                <MelodyNumber aria-hidden="true">{index + 1}.</MelodyNumber>
                {melody.displayTitle}
              </ExerciseLink>
            </li>
          ))}
        </ExerciseList>
      </ExerciseSection>
      <SearchControls role="search" aria-label="Search melody library">
        <SearchField>
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            aria-hidden="true"
            focusable="false"
          >
            <circle cx="10.5" cy="10.5" r="6.5" />
            <path d="m16 16 4 4" />
          </svg>
          <input
            ref={searchInput}
            type="search"
            aria-label="Search melodies"
            aria-controls="melody-list"
            placeholder="Title or composer"
            value={query}
            onChange={event => setQuery(event.target.value)}
          />
          {query && (
            <ClearSearch
              type="button"
              aria-label="Clear search"
              onClick={() => {
                setQuery('');
                searchInput.current?.focus();
              }}
            >
              <span aria-hidden="true">×</span>
            </ClearSearch>
          )}
        </SearchField>
        <SearchResults aria-live="polite" aria-atomic="true">
          Showing {matchingMelodies.length} of {playableMelodies.length}
        </SearchResults>
      </SearchControls>
      {playback.loading && (
        <PlaybackNotice role="status">Loading sound…</PlaybackNotice>
      )}
      {playback.error && (
        <PlaybackNotice role="alert">{playback.error}</PlaybackNotice>
      )}
      {failedDeletion && (
        <PlaybackNotice role="alert">
          Could not delete "{failedDeletion}". Try again.
        </PlaybackNotice>
      )}

      <ColumnHeadings aria-hidden="true">
        <ColumnLabels>
          <span>#</span>
          <span>Title</span>
          <DurationHeading>Time</DurationHeading>
        </ColumnLabels>
      </ColumnHeadings>

      <MelodyList id="melody-list" role="list" aria-label="Melody list">
        {matchingMelodies.map((melody, index) => {
          const seconds = Math.ceil((getMelodyDuration(melody) ?? 0) / 1000);
          const duration = `${Math.floor(seconds / 60)}:${String(
            seconds % 60,
          ).padStart(2, '0')}`;
          const active = playback.activeTitle === melody.title;
          const saved = savedIds.has(melody.title);
          const title = melody.displayTitle ?? melody.title;
          const songId = encodeURIComponent(melody.title);
          const label = `${active ? 'Stop' : 'Play'}: ${title}`;

          return (
            <MelodyListItem key={melody.title} $active={active}>
              <OpenInStudioButton
                type="button"
                title={
                  isRecording
                    ? 'Stop recording to open this melody'
                    : 'Open in Melody Studio'
                }
                disabled={isRecording}
                onClick={() => openInStudio(melody)}
              >
                <MelodyNumber aria-hidden="true">
                  {String(index + 1).padStart(2, '0')}
                </MelodyNumber>
                <MelodyInfo>
                  <MelodyTitle>{title}</MelodyTitle>
                  {melody.author && (
                    <MelodyAuthor>{melody.author}</MelodyAuthor>
                  )}
                </MelodyInfo>
                <MelodyDuration dateTime={`PT${seconds}S`}>
                  {duration}
                </MelodyDuration>
                <OpenArrow
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  aria-hidden="true"
                  focusable="false"
                >
                  <path d="m9 5 7 7-7 7" />
                </OpenArrow>
              </OpenInStudioButton>
              <PlaybackButton
                type="button"
                aria-label={label}
                title={label}
                aria-pressed={active}
                aria-busy={active && playback.loading}
                disabled={!melody.notes.length}
                onClick={() => playback.toggle(melody)}
              >
                <MelodyActionIcon action={active ? 'stop' : 'play'} />
              </PlaybackButton>
              <PlaybackButton
                as={Link}
                to={songId}
                aria-label={`Melody details: ${title}`}
                title="Melody details"
              >
                <MelodyEditorIcon icon="info" />
              </PlaybackButton>
              {(melody.notes.length > 0 || saved) && (
                <RowActions>
                  {melody.notes.length > 0 && (
                    <>
                      <PracticeLink
                        to={`/play-along/${songId}`}
                        aria-label={`Practice: ${title}`}
                        title="Practice"
                      >
                        <MelodyActionIcon action="practice" />
                      </PracticeLink>
                      <PracticeLink
                        to={`/play-along/${songId}?view=guitar`}
                        aria-label={`Guitar practice: ${title}`}
                        title="Guitar practice"
                      >
                        <HeaderIcon name="guitar" />
                      </PracticeLink>
                      <PracticeLink
                        to={`/karaoke/${songId}`}
                        aria-label={`Karaoke: ${title}`}
                        title="Karaoke"
                      >
                        <HeaderIcon name="karaoke" />
                      </PracticeLink>
                    </>
                  )}
                  {saved && (
                    <DeleteButton
                      type="button"
                      aria-label={`Delete melody: ${title}`}
                      title="Delete melody"
                      onClick={() => deleteMelody(melody.title, title)}
                    >
                      <MelodyEditorIcon icon="delete" />
                    </DeleteButton>
                  )}
                </RowActions>
              )}
            </MelodyListItem>
          );
        })}
      </MelodyList>
      {!matchingMelodies.length && (
        <EmptyState>
          <strong>No results</strong>
          <p>Try another title or composer name.</p>
        </EmptyState>
      )}
    </Library>
  );
};

