import styled from 'styled-components';

export const WahControl = ({
  mode,
  onChange,
}: {
  mode: 'auto' | 'cursor';
  onChange: (mode: 'auto' | 'cursor') => void;
}) => (
  <Control>
    Control
    <select
      aria-label="Wah control"
      value={mode}
      onChange={event => {
        onChange(event.target.value === 'cursor' ? 'cursor' : 'auto');
        event.currentTarget.blur();
      }}
      title="Cursor: hold a note and move right or up to open the filter. The gesture controls wah instead of pitch bend. Automatic: rate and auto-sweep are active."
    >
      <option value="auto">Automatic</option>
      <option value="cursor">Cursor</option>
    </select>
  </Control>
);

const Control = styled.label`
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0 0 8px;
  font-size: 11px;
  select {
    width: 100%;
    min-width: 0;
  }
`;
