import { createSelector } from '@reduxjs/toolkit';

import { RootState } from 'app/services/types';

import { initialState, normalizeMelodiesState } from '.';
import { melodies } from '../melodies/melodies';
import { activeSavedTrack } from '../savedMelodies';
import { optimizeMelodyScale } from '../scaleOptimization';

const selectSlice = (state: RootState) => state.melodies || initialState;

export const selectMelodies = createSelector(
  [selectSlice],
  normalizeMelodiesState,
);

const selectLibraryEdits = createSelector(
  [selectMelodies],
  state => state.libraryEdits,
);

export const selectSavedMelodies = createSelector(
  [selectMelodies],
  state => state.savedMelodies,
);

// Playback highlights must not recreate melody objects and restart a session.
export const selectLibraryMelodies = createSelector(
  [selectLibraryEdits, selectSavedMelodies],
  (edits, saved) => [
    ...saved.map(item => ({
      ...activeSavedTrack(item).melody,
      title: item.id,
      displayTitle: item.name,
    })),
    ...melodies.map(melody => {
      const edit = edits[melody.title];
      return edit
        ? optimizeMelodyScale({
            ...melody,
            ...(Array.isArray(edit) ? { notes: edit } : edit),
          })
        : melody;
    }),
  ],
);

const selectRecentMelodyTitles = createSelector(
  [selectMelodies],
  state => state.recentMelodyTitles,
);

export const selectRecentLibraryMelodies = createSelector(
  [selectLibraryMelodies, selectRecentMelodyTitles],
  (library, titles) => {
    if (!titles.length) return library;
    const rank = new Map(titles.map((title, index) => [title, index]));
    return [...library].sort(
      (a, b) =>
        (rank.get(a.title) ?? titles.length) -
        (rank.get(b.title) ?? titles.length),
    );
  },
);
