import { PayloadAction } from '@reduxjs/toolkit';

import { applicatures } from 'app/services/KeyboardService/mappings';
import { scaleApplicatures } from 'app/services/KeyboardService/scaleApplicatures';
import { KeyCode } from 'app/services/KeyboardService/types';
import {
  TimeSignature,
  getTimeSignature,
} from 'app/services/MelodiesService/meter';
import { clampTempo } from 'app/services/MelodiesService/tempo';
import type { Melody } from 'app/services/MelodiesService/types';
import {
  MetronomeRhythm,
  getMetronomeRhythm,
} from 'app/services/MetronomeService/rhythm';
import { Octave } from 'app/services/NotesService';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { splitNote } from 'app/services/NotesService/noteUtils';
import { Timbre } from 'app/services/SynthesizerService';

import { createSlice, useInjectReducer } from 'utils';

import { isMicrotonalScale, microtonalInstrument } from '../microtonal';
import { loadSettings, saveSettings } from '../preferences';
import { Mode, Scale, ScaleSelection, getScale, scales } from '../scales';
import { SettingsState } from './types';

export const initialState: SettingsState = loadSettings();

const slice = createSlice({
  name: 'settings',
  initialState,
  reducers: {
    setOptimizeTablature(state, action: PayloadAction<boolean>) {
      state.optimizeTablature = action.payload;
      state.optimizeFullTablature = false;
      saveSettings(state);
    },
    optimizeFullTablature(state) {
      state.optimizeTablature = true;
      state.optimizeFullTablature = true;
      saveSettings(state);
    },
    setMelodyContext(state, action: PayloadAction<string>) {
      state.melodyContext = action.payload;
      saveSettings(state);
    },
    loadMelodySettings(state, { payload }: PayloadAction<Melody>) {
      state.scale = payload.scale;
      state.mode = payload.mode;
      state.pitch = payload.pitch;
      state.octave = payload.octave;
      if (payload.keyboardStart) {
        const [note, octave] = splitNote(payload.keyboardStart);
        state.pitch = chromaticNotes.indexOf(note);
        state.octave = octave;
      }
      state.timbre = payload.timbre;
      state.bpm = clampTempo(payload.bpm ?? 120);
      state.timeSignature = getTimeSignature(payload.timeSignature);
      state.applicature = payload.keyboardLayout
        ? applicatures.totalQwertyMac
        : scaleApplicatures[payload.scale];
      state.customScale = payload.customScale;
      state.scaleNotes = getScale(
        payload.scale,
        payload.mode,
        payload.customScale,
      );
      saveSettings(state);
    },
    setMetronomeRhythm(state, action: PayloadAction<MetronomeRhythm>) {
      state.metronomeRhythm = getMetronomeRhythm(action.payload);
      saveSettings(state);
    },
    setTimeSignature(state, action: PayloadAction<TimeSignature>) {
      state.timeSignature = getTimeSignature(action.payload);
      saveSettings(state);
    },
    setBpm(state, action: PayloadAction<number>) {
      state.bpm = clampTempo(action.payload);
      saveSettings(state);
    },
    setOctave(state, action: PayloadAction<Octave>) {
      state.octave = action.payload;
      saveSettings(state);
    },
    setPitch(state, action: PayloadAction<number>) {
      state.pitch = action.payload;
      saveSettings(state);
    },
    setApplicature(state, action: PayloadAction<KeyCode[]>) {
      state.applicature = action.payload;
      saveSettings(state);
    },
    applyStudioScale(state, { payload }: PayloadAction<ScaleSelection>) {
      const { scale, mode, pitch, octave } = payload;
      state.scale = scale;
      state.mode = mode;
      state.scaleNotes = getScale(scale, mode);
      state.applicature = scaleApplicatures[scale];
      state.octave = octave;
      state.pitch = pitch;
      state.timbre = 'studioResonantPiano';
      saveSettings(state);
    },
    setScale(state, action: PayloadAction<Scale>) {
      if (
        isMicrotonalScale(action.payload) &&
        microtonalInstrument(state.timbre)?.scale !== action.payload
      )
        return;
      state.scale = action.payload;
      state.applicature = scaleApplicatures[action.payload];
      if (!(scales[state.scale].modes as readonly Mode[]).includes(state.mode))
        state.mode = scales[state.scale].modes[0];
      state.scaleNotes = getScale(state.scale, state.mode, state.customScale);
      saveSettings(state);
    },
    setMode(state, action: PayloadAction<Mode>) {
      if (
        !(scales[state.scale].modes as readonly Mode[]).includes(action.payload)
      )
        return;
      state.mode = action.payload;
      state.scaleNotes = getScale(state.scale, state.mode, state.customScale);
      saveSettings(state);
    },
    setScaleSelection(state, { payload }: PayloadAction<ScaleSelection>) {
      const { scale, mode, pitch, octave } = payload;
      if (
        (scale !== state.scale &&
          isMicrotonalScale(scale) &&
          microtonalInstrument(state.timbre)?.scale !== scale) ||
        !(scales[scale].modes as readonly Mode[]).includes(mode)
      )
        return;
      if (state.scale !== scale) state.applicature = scaleApplicatures[scale];
      if (state.scale !== scale || state.mode !== mode) {
        state.scale = scale;
        state.mode = mode;
        state.scaleNotes = getScale(scale, mode, state.customScale);
      }
      state.pitch = pitch;
      state.octave = octave;
      saveSettings(state);
    },
    setTimbre(state, action: PayloadAction<Timbre>) {
      const profile = microtonalInstrument(action.payload);
      if (
        (profile && state.timbre !== action.payload) ||
        (isMicrotonalScale(state.scale) && profile?.scale !== state.scale)
      ) {
        state.scale = profile?.scale ?? 'diatonic';
        state.mode = scales[state.scale].modes[0];
        state.applicature = scaleApplicatures[state.scale];
        state.scaleNotes = getScale(state.scale, state.mode);
      }
      if (action.payload === 'drums') {
        state.octave = 0;
        state.pitch = 0;
        state.scale = 'chromatic';
        state.mode = 'chromatic';
        state.applicature = applicatures.totalQwertyMac;
        state.scaleNotes = getScale(state.scale, state.mode);
      }
      if (action.payload === 'hang' && state.timbre !== 'hang') {
        state.scale = 'diatonic';
        state.mode = 'aeolian';
        state.pitch = 2;
        state.octave = 3;
        state.applicature = scaleApplicatures.diatonic;
        state.scaleNotes = getScale(state.scale, state.mode);
      }
      state.timbre = action.payload;
      saveSettings(state);
    },
    toggleRecording(state) {
      if (!state.isRecording) state.optimizeFullTablature = false;
      state.isRecording = !state.isRecording;
      saveSettings(state);
    },
  },
});

export const { actions: settingsActions } = slice;

export const useSettingsSlice = () => {
  useInjectReducer({ key: slice.name, reducer: slice.reducer });
  return { actions: slice.actions };
};
