import { useEffect, useRef, useState } from 'react';

import { Project, cloneTrack, newProject } from './project';
import {
  deleteProject,
  readActiveProject,
  readProjects,
  rememberProject,
  writeProject,
} from './storage';

type SaveState = 'loading' | 'saving' | 'saved' | 'error';
type Operation = { run: () => Promise<unknown>; failed: boolean };

export const useProjects = (initial: () => Project) => {
  const fallback = useRef(initial);
  const [project, setProject] = useState(fallback.current);
  const [projects, setProjects] = useState<Project[]>([]);
  const [saveState, setSaveState] = useState<SaveState>('loading');
  const current = useRef(project);
  const history = useRef<{ undo: Project[]; redo: Project[] }>({
    undo: [],
    redo: [],
  }).current;
  const state = useRef({
    alive: true,
    pending: new Map<string, Operation>(),
  }).current;

  useEffect(() => {
    state.alive = true;
    let cancelled = false;
    readProjects().then(
      saved => {
        if (cancelled) return;
        const active =
          saved.find(item => item.id === readActiveProject()) ?? saved[0];
        if (active) {
          current.current = active;
          setProject(active);
        }
        setProjects(saved);
        setSaveState('saved');
      },
      () => {
        if (!cancelled) setSaveState('error');
      },
    );
    return () => {
      cancelled = true;
      state.alive = false;
    };
  }, [state]);

  const persist = (id: string, run: Operation['run']) => {
    const { pending } = state;
    const operation = { run, failed: false };
    const update = () => {
      if (!state.alive) return;
      const failed = Array.from(pending.values()).some(item => item.failed);
      setSaveState(failed ? 'error' : pending.size ? 'saving' : 'saved');
    };
    pending.set(id, operation);
    update();
    void run().then(
      () => {
        if (pending.get(id) !== operation) return;
        pending.delete(id);
        update();
      },
      () => {
        if (pending.get(id) !== operation) return;
        operation.failed = true;
        update();
      },
    );
  };

  const save = (next: Project) => {
    current.current = next;
    setProject(next);
    setProjects(previous => [
      next,
      ...previous.filter(item => item.id !== next.id),
    ]);
    rememberProject(next.id);
    persist(next.id, () => writeProject(next));
  };
  const open = (next: Project) => {
    history.undo = [];
    history.redo = [];
    current.current = next;
    setProject(next);
    rememberProject(next.id);
  };

  return {
    project,
    projects,
    saveState,
    canUndo: !!history.undo.length,
    canRedo: !!history.redo.length,
    edit(update: (previous: Project) => Project) {
      const previous = current.current;
      const next = update(previous);
      if (next === previous) return next;
      history.undo = [...history.undo.slice(-39), previous];
      history.redo = [];
      save(next);
      return next;
    },
    undo() {
      const previous = history.undo.pop();
      if (!previous) return;
      history.redo.push(current.current);
      save(previous);
    },
    redo() {
      const next = history.redo.pop();
      if (!next) return;
      history.undo.push(current.current);
      save(next);
    },
    open,
    create() {
      const next = fallback.current();
      open(next);
      save(next);
    },
    duplicate() {
      const previous = current.current;
      const next = {
        ...newProject(previous.bpm, previous.meter),
        name: `${previous.name} copy`,
        tracks: previous.tracks.map(track => ({
          ...cloneTrack(track),
          name: track.name,
          solo: track.solo,
        })),
      };
      open(next);
      save(next);
    },
    remove() {
      const id = current.current.id;
      const rest = projects.filter(item => item.id !== id);
      setProjects(rest);
      open(rest[0] ?? fallback.current());
      persist(id, () => deleteProject(id));
    },
    retry() {
      const failed = Array.from(state.pending).filter(
        ([, operation]) => operation.failed,
      );
      if (!failed.length) save(current.current);
      else failed.forEach(([id, operation]) => persist(id, operation.run));
    },
  };
};
