import styled from 'styled-components';

import {
  Clip,
  GRID,
  Project,
  Track,
  clipBeats,
  trackLabels,
} from 'app/services/ArrangementService/project';

import { Controls, NameField, NumberField } from './Controls';

export const ArrangementInspector = ({
  project,
  track,
  clip,
  locked,
  onTrack,
  onClip,
  onDeleteClip,
  onMix,
}: {
  project: Project;
  track: Track;
  clip?: Clip;
  locked: boolean;
  onTrack: (track: Track, action: 'up' | 'down' | 'copy' | 'delete') => void;
  onClip: (clip: Clip, track: Track, destination?: Track) => void;
  onDeleteClip: (clip: Clip, track: Track) => void;
  onMix: (track: Track, patch: Partial<Track>) => void;
}) => {
  const index = project.tracks.indexOf(track);
  const unit = clip?.source.kind === 'voice' ? 'sec' : 'beats';
  return (
    <Inspector aria-label="Track and clip controls">
      <section aria-label="Track controls">
        <h2>
          Track <small>{trackLabels[track.kind]}</small>
        </h2>
        <Controls>
          <NameField
            label="Track name"
            value={track.name}
            disabled={locked}
            onCommit={name => onMix(track, { name })}
          />
          <NumberField
            label="Volume (%)"
            value={track.gain * 100}
            min={0}
            max={150}
            onCommit={volume => onMix(track, { gain: volume / 100 })}
          />
          <NumberField
            label="Pan (L −100 / R 100)"
            value={track.pan * 100}
            min={-100}
            max={100}
            onCommit={pan => onMix(track, { pan: pan / 100 })}
          />
        </Controls>
        <Controls>
          <button
            type="button"
            disabled={locked || index === 0}
            onClick={() => onTrack(track, 'up')}
          >
            Move up
          </button>
          <button
            type="button"
            disabled={locked || index === project.tracks.length - 1}
            onClick={() => onTrack(track, 'down')}
          >
            Move down
          </button>
          <button
            type="button"
            disabled={locked}
            onClick={() => onTrack(track, 'copy')}
          >
            Duplicate track
          </button>
          <button
            type="button"
            disabled={locked}
            onClick={() => onTrack(track, 'delete')}
          >
            Delete track
          </button>
        </Controls>
      </section>
      <section aria-label="Clip controls">
        <h2>Clip</h2>
        {clip ? (
          <>
            <Controls>
              <NameField
                label="Clip name"
                value={clip.name}
                disabled={locked}
                onCommit={name => onClip({ ...clip, name }, track)}
              />
              <NumberField
                label="Start beat"
                value={clip.start + 1}
                min={1}
                disabled={locked}
                onCommit={start => onClip({ ...clip, start: start - 1 }, track)}
              />
              <NumberField
                label={`Trim start (${unit})`}
                value={clip.offset}
                min={0}
                max={Math.max(
                  0,
                  clip.sourceLength - Math.min(0.001, clip.sourceLength),
                )}
                disabled={locked}
                onCommit={offset =>
                  onClip(
                    {
                      ...clip,
                      offset,
                      length: Math.min(clip.length, clip.sourceLength - offset),
                    },
                    track,
                  )
                }
              />
              <NumberField
                label={`Length (${unit})`}
                value={clip.length}
                min={Math.min(0.001, clip.length)}
                max={clip.sourceLength - clip.offset}
                disabled={locked}
                onCommit={length => onClip({ ...clip, length }, track)}
              />
              {project.tracks.some(
                item => item.kind === track.kind && item.id !== track.id,
              ) && (
                <label>
                  Move to track
                  <select
                    value={track.id}
                    disabled={locked}
                    onChange={event => {
                      const destination = project.tracks.find(
                        item => item.id === event.target.value,
                      );
                      if (destination) onClip(clip, track, destination);
                    }}
                  >
                    {project.tracks
                      .filter(item => item.kind === track.kind)
                      .map(item => (
                        <option key={item.id} value={item.id}>
                          {item.name}
                        </option>
                      ))}
                  </select>
                </label>
              )}
            </Controls>
            <Controls>
              <button
                type="button"
                disabled={locked}
                onClick={() =>
                  onClip(
                    {
                      ...clip,
                      id: '',
                      start:
                        Math.ceil(
                          (clip.start + clipBeats(clip, project.bpm)) / GRID,
                        ) * GRID,
                    },
                    track,
                  )
                }
              >
                Duplicate clip
              </button>
              <button
                type="button"
                disabled={locked}
                onClick={() => onDeleteClip(clip, track)}
              >
                Delete clip
              </button>
            </Controls>
          </>
        ) : (
          <p>Select a clip on the timeline to move or trim it.</p>
        )}
      </section>
    </Inspector>
  );
};

const Inspector = styled.div`
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  section {
    display: grid;
    gap: 10px;
    align-content: start;
    padding: 13px;
    border-radius: 10px;
    border: 1px solid ${p => p.theme.border};
    background: ${p => p.theme.surface};
  }
  h2 {
    margin: 0;
    font: 700 14px/1.4 system-ui, sans-serif;
  }
  h2 small,
  p {
    color: ${p => p.theme.textSecondary};
    font-size: 12px;
  }
  p {
    margin: 0;
  }
  @media (max-width: 790px) {
    grid-template-columns: 1fr;
  }
`;
