import { sampleKey } from 'app/services/DrumMachineService/samples';
import {
  decodeDrumClip,
  getDrumVoice,
  scheduleDrumVoice,
} from 'app/services/DrumMachineService/voices';
import {
  EXPORT_SAMPLE_RATE,
  encodeWav,
  getEffectsTail,
  scheduleExportNotes,
} from 'app/services/MelodyExportService/audio';
import {
  getInstrumentAudioContext,
  prepareInstrumentSample,
  resumeAudio,
  sampleDefinition,
} from 'app/services/SynthesizerService';
import { createEffectsRack } from 'app/services/SynthesizerService/effects';

import {
  ClipSource,
  Project,
  clipNotes,
  clipWindow,
  isTrackAudible,
  projectEnd,
  secondsPerBeat,
} from './project';

const voiceBuffers = new WeakMap<Blob, AudioBuffer>();
const decoder = getInstrumentAudioContext;

export const decodeVoice = async (blob: Blob) => {
  const previous = voiceBuffers.get(blob);
  if (previous) return previous;
  const buffer = await decoder().decodeAudioData(await blob.arrayBuffer());
  voiceBuffers.set(blob, buffer);
  return buffer;
};

export const waveformPeaks = (buffer: AudioBuffer, count = 96) => {
  const samples = buffer.getChannelData(0);
  return Array.from({ length: count }, (_, index) => {
    const from = Math.floor((index * samples.length) / count);
    const to = Math.floor(((index + 1) * samples.length) / count);
    let peak = 0;
    for (
      let i = from;
      i < to;
      i += Math.max(1, Math.floor((to - from) / 256))
    ) {
      peak = Math.max(peak, Math.abs(samples[i]));
    }
    return peak;
  });
};

const prepareSources = async (project: Project) => {
  const voices = new Map<
    string,
    NonNullable<ReturnType<typeof getDrumVoice>>
  >();
  const drums = new Map<string, Promise<void>>();
  const sources = new Map<ClipSource, Promise<AudioBuffer | undefined>>();
  for (const track of project.tracks) {
    for (const { source } of track.clips) {
      if (sources.has(source)) continue;
      if (source.kind === 'voice') {
        sources.set(source, decodeVoice(source.audio));
      } else if (source.kind === 'melody') {
        sources.set(source, prepareInstrumentSample(source.timbre));
      } else {
        source.hits.forEach(({ sample }) => {
          const key = sampleKey(sample);
          if (drums.has(key)) return;
          const pending =
            sample.kind === 'builtin'
              ? prepareInstrumentSample('drums')
              : sample.kind === 'instrument'
              ? prepareInstrumentSample(sample.timbre)
              : decodeDrumClip(decoder(), sample);
          drums.set(
            key,
            pending.then(buffer => {
              const voice = getDrumVoice(sample, buffer);
              if (!voice)
                throw new Error('Could not read a sample in this beat.');
              voices.set(key, voice);
            }),
          );
        });
      }
    }
  }
  const [buffers] = await Promise.all([
    Promise.all(
      Array.from(
        sources,
        async ([source, pending]) => [source, await pending] as const,
      ),
    ),
    Promise.all(drums.values()),
  ]);
  return { buffers: new Map(buffers), voices };
};

const createMixer = (
  audio: BaseAudioContext,
  project: Project,
  { buffers, voices }: Awaited<ReturnType<typeof prepareSources>>,
) => {
  const master = audio.createDynamicsCompressor();
  master.threshold.value = -6;
  master.ratio.value = 8;
  master.connect(audio.destination);
  const racks: ReturnType<typeof createEffectsRack>[] = [];
  const playing = new Set<AudioBufferSourceNode>();
  const trackNodes = project.tracks.map(track => {
    const gain = audio.createGain();
    const pan = audio.createStereoPanner();
    gain.connect(pan);
    pan.connect(master);
    const inputs = new Map<ClipSource, AudioNode>();
    return { gain, pan, inputs, track };
  });
  const register = (source: AudioBufferSourceNode) => {
    playing.add(source);
    source.onended = () => {
      playing.delete(source);
      source.disconnect();
    };
  };
  const setMix = (current: Project, smooth = true) => {
    const solo = current.tracks.some(track => track.solo);
    trackNodes.forEach(({ gain, pan }, index) => {
      const track = current.tracks[index];
      const level = isTrackAudible(track, solo) ? track.gain : 0;
      if (smooth) {
        gain.gain.setTargetAtTime(level, audio.currentTime, 0.008);
        pan.pan.setTargetAtTime(track.pan, audio.currentTime, 0.008);
      } else {
        gain.gain.value = level;
        pan.pan.value = track.pan;
      }
    });
  };
  setMix(project, false);

  const unit = secondsPerBeat(project.bpm);
  const schedule = (from: number, to: number, at: number) => {
    trackNodes.forEach(({ gain, inputs, track }) => {
      track.clips.forEach(clip => {
        const window = clipWindow(clip, project.bpm, from, to);
        if (!window) return;
        const { source } = clip;
        const start = at + (window.start - from) * unit;
        const duration = (window.end - window.start) * unit;
        if (source.kind === 'voice') {
          const voice = audio.createBufferSource();
          const envelope = audio.createGain();
          const fade = Math.min(0.005, duration / 2);
          voice.buffer = buffers.get(source)!;
          voice.connect(envelope);
          envelope.connect(gain);
          envelope.gain.setValueAtTime(0, start);
          envelope.gain.linearRampToValueAtTime(1, start + fade);
          envelope.gain.setValueAtTime(1, start + duration - fade);
          envelope.gain.linearRampToValueAtTime(0, start + duration);
          voice.start(start, window.sourceStart, duration);
          register(voice);
          return;
        }
        let input = inputs.get(source);
        if (!input) {
          const rack = createEffectsRack(audio, gain, source.effects);
          racks.push(rack);
          input = rack.input;
          if (source.kind === 'drums') {
            const volume = audio.createGain();
            volume.gain.value = source.volume;
            volume.connect(input);
            input = volume;
          }
          inputs.set(source, input);
        }
        if (source.kind === 'melody') {
          const time = (beat: number) =>
            (start + (beat - window.sourceStart) * unit) * 1000;
          const notes = clipNotes(
            source.notes,
            window.sourceStart,
            window.sourceEnd,
          ).map(note => ({
            ...note,
            start: time(note.start),
            end: time(note.end),
          }));
          scheduleExportNotes(
            audio,
            buffers.get(source)!,
            input,
            notes,
            source.timbre === 'drums',
            sampleDefinition(source.timbre),
            register,
          );
        } else {
          source.hits.forEach(hit => {
            if (hit.beat < window.sourceStart || hit.beat >= window.sourceEnd)
              return;
            const voice = voices.get(sampleKey(hit.sample))!;
            const hitTime = start + (hit.beat - window.sourceStart) * unit;
            const duration = Math.min(
              voice.duration,
              (window.sourceEnd - hit.beat) * unit,
            );
            const { source: node } = scheduleDrumVoice(audio, input!, hitTime, {
              ...voice,
              duration,
            });
            register(node);
          });
        }
      });
    });
  };

  return {
    schedule,
    setMix,
    dispose() {
      master.disconnect();
      playing.forEach(source => {
        source.onended = null;
        source.stop();
        source.disconnect();
      });
      playing.clear();
      racks.forEach(rack => rack.dispose());
      trackNodes.forEach(({ gain, pan }) => {
        gain.disconnect();
        pan.disconnect();
      });
    },
  };
};

export const preparePlayback = async (project: Project) => {
  const audio = decoder();
  const [, sources] = await Promise.all([
    resumeAudio(),
    prepareSources(project),
  ]);
  // Keep preparation side effect free until the initiating request is accepted.
  return () => createMixer(audio, project, sources);
};

export const mixTail = (project: Project) => {
  const tail = project.tracks.reduce(
    (longest, track) =>
      track.clips.reduce((max, { source }) => {
        if (source.kind === 'voice') return max;
        const release =
          source.kind === 'melody'
            ? sampleDefinition(source.timbre).release
            : 0;
        return Math.max(max, getEffectsTail(source.effects) + release);
      }, longest),
    0.1,
  );
  return Math.min(12, tail);
};

export const exportMix = async (project: Project) => {
  if (!window.OfflineAudioContext)
    throw new Error('WAV export is unavailable in this browser.');
  const end = projectEnd(project);
  const seconds = end * secondsPerBeat(project.bpm);
  const audio = new OfflineAudioContext(
    2,
    Math.ceil((seconds + mixTail(project)) * EXPORT_SAMPLE_RATE),
    EXPORT_SAMPLE_RATE,
  );
  const mixer = createMixer(audio, project, await prepareSources(project));
  try {
    mixer.schedule(0, end, 0);
    return new Blob([encodeWav(await audio.startRendering())], {
      type: 'audio/wav',
    });
  } finally {
    mixer.dispose();
  }
};
