import type { AnyAction } from '@reduxjs/toolkit';
import { batch, useDispatch, useSelector, useStore } from 'react-redux';
import styled from 'styled-components';

import { getMelodyDuration } from 'app/services/MelodiesService';
import type { Melody } from 'app/services/MelodiesService/types';
import { getMelodyBpm } from 'app/services/MelodiesService/useCurrentMelody';
import {
  notesActions,
  selectNotes,
  selectRecordingProject,
} from 'app/services/NotesService';
import { settingsActions } from 'app/services/SettingsService';
import type { RootState } from 'app/services/types';

import { getTimbrePresentation } from './TimbrePicker/catalog';

const time = (milliseconds: number) => {
  const tenths = Math.round(milliseconds / 100);
  return `${Math.floor(tenths / 600)}:${((tenths % 600) / 10)
    .toFixed(1)
    .padStart(4, '0')}`;
};

export const StudioParts = ({
  melody,
  onStop,
}: {
  melody: Melody;
  onStop: () => void;
}) => {
  const dispatch = useDispatch();
  const store = useStore<RootState>();
  const project = useSelector(selectRecordingProject);
  const active = project.tracks.find(
    track => track.id === project.activeTrackId,
  )!;
  const change = (action: AnyAction) => {
    onStop();
    batch(() => {
      dispatch(action);
      const next = selectNotes(store.getState()).melody;
      dispatch(
        settingsActions.loadMelodySettings({
          ...next,
          bpm: getMelodyBpm(next),
        }),
      );
    });
  };

  return (
    <Parts>
      <summary>
        Parts · {active.name} ({project.tracks.length})
      </summary>
      <div className="parts-content">
        <div role="group" aria-label="Composition parts" className="parts-list">
          {project.tracks.map(track => {
            const part = track.id === active.id ? melody : track.melody;
            return (
              <label key={track.id} className="part">
                <input
                  type="radio"
                  name="recording-track"
                  aria-label={track.name}
                  checked={track.id === active.id}
                  onChange={() =>
                    change(
                      notesActions.selectRecordingTrack({
                        id: track.id,
                        current: melody,
                      }),
                    )
                  }
                />
                <span>
                  <strong>{track.name}</strong>
                  <small>
                    {getTimbrePresentation(part.timbre).label} ·{' '}
                    {part.notes.length} notes ·{' '}
                    {time(part.notes[0]?.start ?? 0)}–
                    {time(getMelodyDuration(part))}
                  </small>
                </span>
              </label>
            );
          })}
        </div>
        <form
          key={`${active.id}:${active.name}`}
          onSubmit={event => {
            event.preventDefault();
            const name = new FormData(event.currentTarget).get('trackName');
            if (typeof name === 'string' && name.trim())
              dispatch(
                notesActions.renameRecordingTrack({ id: active.id, name }),
              );
          }}
        >
          <label>
            Track name
            <input
              name="trackName"
              defaultValue={active.name}
              maxLength={120}
              required
            />
          </label>
          <button type="submit">Rename</button>
          <button
            type="button"
            onClick={() =>
              change(notesActions.addRecordingTrack({ current: melody }))
            }
          >
            Add track
          </button>
          <button
            type="button"
            disabled={project.tracks.length < 2}
            onClick={() => {
              if (
                !melody.notes.length ||
                window.confirm(
                  `Delete track “${active.name}” and all its notes?`,
                )
              )
                change(
                  notesActions.removeRecordingTrack({
                    id: active.id,
                    current: melody,
                  }),
                );
            }}
          >
            Delete track
          </button>
        </form>
        {!!melody.notes[0]?.start && (
          <p>Silence before the first note: {time(melody.notes[0].start)}.</p>
        )}
        {!!active.warnings?.length && (
          <ul>
            {active.warnings.map(warning => (
              <li key={warning}>{warning}</li>
            ))}
          </ul>
        )}
        {melody.source && (
          <p>
            <a href={melody.source.url} target="_blank" rel="noreferrer">
              Score source: {melody.source.label}
            </a>{' '}
            · {melody.source.section} {melody.source.adaptation}
          </p>
        )}
        <p>
          Save to Melodies keeps all parts. Studio playback, Practice, and
          exports use the selected part.
        </p>
      </div>
    </Parts>
  );
};

const Parts = styled.details`
  margin-bottom: 10px;
  font-size: 13px;
  summary {
    cursor: pointer;
    padding: 7px 9px;
    width: fit-content;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    background: ${p => p.theme.surface};
    overflow-wrap: anywhere;
  }
  .parts-content {
    display: grid;
    gap: 9px;
    margin-top: 5px;
    padding: 10px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    background: ${p => p.theme.surface};
  }
  .parts-list,
  form {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px 10px;
  }
  .part,
  form label {
    display: flex;
    align-items: center;
    gap: 5px;
  }
  .part {
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    padding: 6px 8px;
    cursor: pointer;
    overflow-wrap: anywhere;
  }
  .part span {
    min-width: 0;
    display: grid;
  }
  p,
  small {
    color: ${p => p.theme.textSecondary};
    margin: 0;
  }
`;
