import { nanoid } from '@reduxjs/toolkit';
import { useEffect, useRef, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useSelector } from 'react-redux';
import styled from 'styled-components';

import { exportMix } from 'app/services/ArrangementService/audio';
import {
  Clip,
  Project,
  Track,
  beatTrack,
  cloneTrack,
  melodyTrack,
  newProject,
  newTrack,
  projectEnd,
  projectFits,
  secondsPerBeat,
} from 'app/services/ArrangementService/project';
import { useProjects } from 'app/services/ArrangementService/useProjects';
import { useTransport } from 'app/services/ArrangementService/useTransport';
import {
  loadSavedDrumBeats,
  suggestBeatName,
} from 'app/services/DrumMachineService/beatLibrary';
import { useDrumMachine } from 'app/services/DrumMachineService/context';
import { selectEffects } from 'app/services/EffectsService/selectors';
import { stopMelody } from 'app/services/MelodiesService';
import {
  TIME_SIGNATURES,
  TimeSignature,
  getBeatsPerMeasure,
} from 'app/services/MelodiesService/meter';
import { readSavedMelodies } from 'app/services/MelodiesService/savedMelodies';
import {
  MAX_TEMPO,
  MIN_TEMPO,
  clampTempo,
} from 'app/services/MelodiesService/tempo';
import { useCurrentMelody } from 'app/services/MelodiesService/useCurrentMelody';
import {
  downloadBlob,
  safeExportTitle,
} from 'app/services/MelodyExportService';
import { selectRecordingProject } from 'app/services/NotesService';
import { selectSettings } from 'app/services/SettingsService';

import {
  Controls,
  NameField,
  NumberField,
} from 'app/components/Arrangement/Controls';
import { ArrangementInspector } from 'app/components/Arrangement/Inspector';
import { ArrangementTimeline } from 'app/components/Arrangement/Timeline';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

import { isFormInputTarget } from 'utils/isFormInputTarget';

const clock = (seconds: number) => {
  const tenth = Math.floor(seconds * 10);
  return `${String(Math.floor(tenth / 600)).padStart(2, '0')}:${String(
    Math.floor(tenth / 10) % 60,
  ).padStart(2, '0')}.${tenth % 10}`;
};

export const ArrangementPage = () => {
  const studio = useSelector(selectRecordingProject);
  const { bpm, timeSignature, isRecording } = useSelector(selectSettings);
  const { instruments } = useSelector(selectEffects);
  const current = useCurrentMelody(
    studio.tracks.find(track => track.id === studio.activeTrackId)?.melody,
  );
  const drum = useDrumMachine();
  const { stop: stopDrums } = drum;
  const projects = useProjects(() => newProject(bpm, timeSignature));
  const { project, saveState } = projects;
  const [error, setError] = useState('');
  const transport = useTransport(project, setError);
  const [savedMelodies] = useState(readSavedMelodies);
  const [savedBeats] = useState(loadSavedDrumBeats);
  const [melodyId, setMelodyId] = useState('');
  const [beatId, setBeatId] = useState('');
  const [repeats, setRepeats] = useState(4);
  const [zoom, setZoom] = useState(36);
  const [exporting, setExporting] = useState(false);
  const [selection, setSelection] = useState<{
    trackId: string;
    clipId?: string;
  }>();
  const track = project.tracks.find(item => item.id === selection?.trackId);
  const clip = track?.clips.find(item => item.id === selection?.clipId);
  const idle = transport.phase === 'idle';
  const playing = transport.phase === 'playing';
  const locked = !idle || exporting || saveState === 'loading';
  const end = projectEnd(project);
  const measure = getBeatsPerMeasure(project.meter);
  const studioHasNotes =
    !isRecording &&
    studio.tracks.some(
      item =>
        (item.id === studio.activeTrackId ? current : item.melody)?.notes
          .length,
    );

  useEffect(() => {
    stopDrums();
    stopMelody();
  }, [stopDrums]);

  const select = (item: Track, part?: Clip) =>
    setSelection({ trackId: item.id, clipId: part?.id });
  const commit = (next: Project) => {
    if (!projectFits(next)) {
      setError('The arrangement can be up to 5 minutes long.');
      return false;
    }
    setError('');
    projects.edit(() => next);
    return true;
  };

  const addMelody = () => {
    const saved = savedMelodies.find(item => item.id === melodyId);
    const source = saved ?? studio;
    const name =
      saved?.name ?? current?.displayTitle ?? (studio.title || 'Studio melody');
    try {
      const imported = source.tracks.flatMap(item => {
        const live = !saved && item.id === studio.activeTrackId;
        const melody = live ? current : item.melody;
        const result =
          melody &&
          melodyTrack(
            source.tracks.length > 1 ? item.name : name,
            melody,
            transport.position,
            instruments,
            live,
          );
        return result ? [result] : [];
      });
      if (
        imported.length &&
        commit({ ...project, tracks: [...project.tracks, ...imported] })
      )
        select(imported[0], imported[0].clips[0]);
    } catch (cause) {
      setError(
        cause instanceof Error ? cause.message : 'Could not add this melody.',
      );
    }
  };

  const addBeat = () => {
    const saved = savedBeats.find(item => item.id === beatId);
    const source = saved ?? {
      state: drum.state,
      bpm: drum.bpm,
      timeSignature,
      effects: drum.effects,
    };
    const next = beatTrack(
      saved?.name ?? suggestBeatName(source),
      source,
      transport.position,
      repeats,
    );
    if (!next) {
      setError('This beat has no hits on unmuted rows.');
      return;
    }
    if (commit({ ...project, tracks: [...project.tracks, next] }))
      select(next, next.clips[0]);
  };

  const updateClip = (next: Clip, lane: Track, destination = lane) => {
    const copy = !next.id;
    const moved = destination.id !== lane.id;
    const part = copy
      ? { ...next, id: nanoid(), name: `${next.name} copy` }
      : next;
    const updated = project.tracks.map(item => {
      if (item.id === destination.id)
        return {
          ...item,
          clips:
            copy || moved
              ? [...item.clips, part]
              : item.clips.map(candidate =>
                  candidate.id === part.id ? part : candidate,
                ),
        };
      if (item.id === lane.id)
        return {
          ...item,
          clips: item.clips.filter(candidate => candidate.id !== part.id),
        };
      return item;
    });
    if (commit({ ...project, tracks: updated })) select(destination, part);
  };
  const deleteClip = (part: Clip, lane: Track) => {
    if (
      commit({
        ...project,
        tracks: project.tracks.map(item =>
          item.id === lane.id
            ? {
                ...item,
                clips: item.clips.filter(candidate => candidate.id !== part.id),
              }
            : item,
        ),
      })
    )
      select(lane);
  };
  const trackAction = (
    lane: Track,
    action: 'up' | 'down' | 'copy' | 'delete',
  ) => {
    const updated = project.tracks.slice();
    const index = updated.indexOf(lane);
    const delta = action === 'up' ? -1 : 1;
    if (action === 'delete') {
      updated.splice(index, 1);
      setSelection(undefined);
    } else if (action === 'copy') {
      const copy = cloneTrack(lane);
      updated.splice(index + 1, 0, copy);
      select(copy);
    } else {
      [updated[index], updated[index + delta]] = [
        updated[index + delta],
        updated[index],
      ];
    }
    commit({ ...project, tracks: updated });
  };
  const mix = (item: Track, patch: Partial<Track>) => {
    if (saveState === 'loading' || exporting) return;
    const next = projects.edit(previous => {
      const before = previous.tracks.find(
        candidate => candidate.id === item.id,
      );
      if (
        !before ||
        Object.entries(patch).every(
          ([key, value]) => before[key as keyof Track] === value,
        )
      )
        return previous;
      return {
        ...previous,
        tracks: previous.tracks.map(candidate =>
          candidate === before ? { ...candidate, ...patch } : candidate,
        ),
      };
    });
    transport.updateMix(next);
  };

  const resetForProject = (action: () => void) => {
    setError('');
    setSelection(undefined);
    transport.seek(0);
    action();
  };
  const startPlayback = () => {
    stopDrums();
    stopMelody();
    void transport.play();
  };
  const record = () => {
    stopDrums();
    stopMelody();
    const armed = track?.kind === 'voice' ? track.id : undefined;
    void transport.record(take => {
      const next = projects.edit(previous => {
        const lane = previous.tracks.find(item => item.id === armed);
        if (lane)
          return {
            ...previous,
            tracks: previous.tracks.map(item =>
              item.id === armed
                ? { ...item, clips: [...item.clips, take] }
                : item,
            ),
          };
        return {
          ...previous,
          tracks: [
            ...previous.tracks,
            newTrack(
              'voice',
              `Voice ${
                previous.tracks.filter(item => item.kind === 'voice').length + 1
              }`,
              [take],
            ),
          ],
        };
      });
      const lane = next.tracks.find(item =>
        item.clips.some(part => part.id === take.id),
      );
      if (lane) select(lane, take);
    });
  };

  const download = async () => {
    setExporting(true);
    setError('');
    try {
      const filename = safeExportTitle(project.name, 'arrangement-mix');
      downloadBlob(await exportMix(project), `${filename}.wav`);
    } catch (cause) {
      setError(
        cause instanceof Error ? cause.message : 'Could not export the mix.',
      );
    } finally {
      setExporting(false);
    }
  };

  const shortcuts = useRef<(event: KeyboardEvent) => void>();
  shortcuts.current = event => {
    if (
      event.defaultPrevented ||
      event.isComposing ||
      isFormInputTarget(event.target)
    )
      return;
    if (
      event.code === 'Space' &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey
    ) {
      if (event.target instanceof Element && event.target.closest('button, a'))
        return;
      if (playing) transport.pause();
      else if (!locked && end) startPlayback();
      else return;
    } else if (!locked && event.key === 'Home') {
      transport.seek(0);
    } else if (!locked && event.key === 'Delete' && clip && track) {
      deleteClip(clip, track);
    } else if (
      !locked &&
      (event.metaKey || event.ctrlKey) &&
      event.key.toLowerCase() === 'z'
    ) {
      if (event.shiftKey) projects.redo();
      else projects.undo();
    } else return;
    event.preventDefault();
  };
  useEffect(() => {
    const handle = (event: KeyboardEvent) => {
      if (!event.repeat) shortcuts.current?.(event);
    };
    window.addEventListener('keydown', handle);
    return () => window.removeEventListener('keydown', handle);
  }, []);

  return (
    <Page>
      <Helmet>
        <title>Arrangement</title>
        <link rel="canonical" href="https://melodygenerator.app/arrangement" />
        <meta
          name="description"
          content="Arrange melodies and beats, record your voice, and export a mix in Melody Generator."
        />
      </Helmet>
      <Heading>
        <div>
          <h1>Arrangement</h1>
          <p>
            Arrange melodies and beats, then record your voice over the mix.
          </p>
        </div>
        <button type="button" disabled={locked || !end} onClick={download}>
          {exporting ? 'Exporting…' : 'Export WAV'}
        </button>
      </Heading>

      <Panel aria-label="Project controls">
        <Controls>
          <NameField
            key={project.id}
            label="Project name"
            value={project.name}
            disabled={locked}
            onCommit={name =>
              projects.edit(previous => ({ ...previous, name }))
            }
          />
          <label>
            Open project
            <select
              aria-label="Open project"
              className="project-select"
              value={project.id}
              disabled={locked || !projects.projects.length}
              onChange={event => {
                const next = projects.projects.find(
                  item => item.id === event.target.value,
                );
                if (next) resetForProject(() => projects.open(next));
              }}
            >
              {!projects.projects.some(item => item.id === project.id) && (
                <option value={project.id}>{project.name}</option>
              )}
              {projects.projects.map(item => (
                <option value={item.id} key={item.id}>
                  {item.name}
                </option>
              ))}
            </select>
          </label>
          <button
            type="button"
            disabled={locked}
            onClick={() => resetForProject(projects.create)}
          >
            New project
          </button>
          <button
            type="button"
            disabled={locked}
            onClick={() => resetForProject(projects.duplicate)}
          >
            Duplicate project
          </button>
          <button
            type="button"
            disabled={
              locked || !projects.projects.some(item => item.id === project.id)
            }
            onClick={() => {
              if (window.confirm(`Delete “${project.name}” from this browser?`))
                resetForProject(projects.remove);
            }}
          >
            Delete project
          </button>
        </Controls>
        <Status role="status">
          {saveState === 'error' ? (
            <>
              Could not save to this browser.{' '}
              <button type="button" disabled={locked} onClick={projects.retry}>
                Retry save
              </button>
            </>
          ) : saveState === 'saving' ? (
            'Saving…'
          ) : saveState === 'loading' ? (
            'Loading projects…'
          ) : projects.projects.some(item => item.id === project.id) ? (
            'Saved on this device'
          ) : (
            'Projects save on this device as you work.'
          )}
        </Status>
      </Panel>

      <Panel aria-label="Transport">
        <Controls>
          <TransportPosition aria-label="Playhead position">
            <strong>
              {clock(transport.position * secondsPerBeat(project.bpm))}
            </strong>
            <small>
              BAR {Math.floor(transport.position / measure) + 1} · BEAT{' '}
              {Math.floor(
                (transport.position % measure) /
                  (project.meter.endsWith('/8') ? 0.5 : 1),
              ) + 1}
            </small>
          </TransportPosition>
          <button
            type="button"
            className="primary"
            disabled={!playing && (locked || !end)}
            onClick={playing ? transport.pause : startPlayback}
          >
            {playing ? 'Pause' : 'Play'}
          </button>
          <button
            type="button"
            disabled={
              transport.phase === 'finishing' || (idle && !transport.position)
            }
            onClick={transport.stop}
          >
            Stop
          </button>
          <button
            type="button"
            className="record"
            aria-pressed={transport.phase === 'recording'}
            disabled={locked}
            onClick={record}
          >
            Record voice
          </button>
          <button
            type="button"
            aria-pressed={transport.loop}
            disabled={locked}
            onClick={() => transport.setLoop(!transport.loop)}
          >
            Loop
          </button>
          <NumberField
            label="Tempo (BPM)"
            value={project.bpm}
            min={MIN_TEMPO}
            max={MAX_TEMPO}
            disabled={locked}
            onCommit={value => {
              const next = clampTempo(value);
              if (next !== project.bpm) commit({ ...project, bpm: next });
            }}
          />
          <label>
            Meter
            <select
              value={project.meter}
              disabled={locked}
              onChange={event =>
                commit({
                  ...project,
                  meter: event.target.value as TimeSignature,
                })
              }
            >
              {TIME_SIGNATURES.map(meter => (
                <option key={meter}>{meter}</option>
              ))}
            </select>
          </label>
          <label>
            Zoom
            <select
              value={zoom}
              onChange={event => setZoom(Number(event.target.value))}
            >
              <option value={18}>50%</option>
              <option value={36}>100%</option>
              <option value={54}>150%</option>
              <option value={72}>200%</option>
            </select>
          </label>
        </Controls>
        {transport.phase === 'loading' && (
          <Status role="status">Loading sounds…</Status>
        )}
        {transport.phase === 'arming' && (
          <Status role="status">Preparing to record…</Status>
        )}
        {transport.phase === 'recording' && (
          <Status role="status">
            Recording voice. Press Stop to keep the take.
          </Status>
        )}
        {transport.phase === 'finishing' && (
          <Status role="status">Adding voice take…</Status>
        )}
      </Panel>

      <Sources aria-label="Add to arrangement">
        <Controls role="group" aria-label="Melody source">
          <label>
            Melody Studio
            <select
              value={melodyId}
              disabled={locked}
              onChange={event => setMelodyId(event.target.value)}
            >
              <option value="">
                Current recording{studioHasNotes ? '' : ' (empty)'}
              </option>
              {savedMelodies.map(item => (
                <option key={item.id} value={item.id}>
                  {item.name}
                </option>
              ))}
            </select>
          </label>
          <button
            type="button"
            disabled={locked || (!melodyId && !studioHasNotes)}
            onClick={addMelody}
          >
            Add melody
          </button>
        </Controls>
        <Controls role="group" aria-label="Beat source">
          <label>
            Drum Machine
            <select
              value={beatId}
              disabled={locked}
              onChange={event => setBeatId(event.target.value)}
            >
              <option value="">Current Drum Machine beat</option>
              {savedBeats.map(item => (
                <option key={item.id} value={item.id}>
                  {item.name}
                </option>
              ))}
            </select>
          </label>
          <NumberField
            label="Bars"
            value={repeats}
            min={1}
            max={64}
            disabled={locked}
            onCommit={value => setRepeats(Math.round(value))}
          />
          <button type="button" disabled={locked} onClick={addBeat}>
            Add beat
          </button>
        </Controls>
      </Sources>

      {error && <Alert role="alert">{error}</Alert>}
      <TimelineTools>
        <span>Arrangement</span>
        <div>
          <button
            type="button"
            disabled={locked || !projects.canUndo}
            onClick={projects.undo}
          >
            Undo
          </button>
          <button
            type="button"
            disabled={locked || !projects.canRedo}
            onClick={projects.redo}
          >
            Redo
          </button>
          <button
            type="button"
            disabled={locked}
            onClick={() => {
              const next = newTrack(
                'voice',
                `Voice ${
                  project.tracks.filter(item => item.kind === 'voice').length +
                  1
                }`,
              );
              if (commit({ ...project, tracks: [...project.tracks, next] }))
                select(next);
            }}
          >
            Add voice track
          </button>
        </div>
      </TimelineTools>
      <ArrangementTimeline
        project={project}
        position={transport.position}
        zoom={zoom}
        locked={locked}
        following={playing || transport.phase === 'recording'}
        trackId={track?.id}
        clipId={clip?.id}
        onSeek={transport.seek}
        onSelect={select}
        onMix={mix}
        onMove={(lane, part, start) => {
          if (start !== part.start) updateClip({ ...part, start }, lane);
        }}
      />
      {track && (
        <ArrangementInspector
          project={project}
          track={track}
          clip={clip}
          locked={locked}
          onTrack={trackAction}
          onClip={updateClip}
          onDeleteClip={deleteClip}
          onMix={mix}
        />
      )}
      <Hint>
        Click the ruler to set the playhead. Drag clips to arrange them. Use
        headphones when recording over other tracks.
      </Hint>
    </Page>
  );
};

const Page = styled(PageWrapper)`
  display: grid;
  max-width: 1440px;
  gap: 12px;
  h1 {
    margin: 0;
    font-size: clamp(28px, 4vw, 40px);
    line-height: 1.15;
    text-align: left;
  }
  button {
    min-height: 36px;
    padding: 5px 10px;
    white-space: nowrap;
    font-size: 13px;
  }
  button[aria-pressed='true'] {
    border-color: ${p => p.theme.primary};
  }
  .project-select {
    max-width: min(230px, 100%);
  }
  button.primary:enabled {
    border-color: ${p => p.theme.primary};
    color: ${p => p.theme.primary};
  }
  button.record::before {
    content: '';
    display: inline-block;
    vertical-align: 1px;
    width: 8px;
    height: 8px;
    margin-right: 6px;
    border-radius: 50%;
    background: #d84d67;
  }
`;
const Heading = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 12px;
  p {
    margin: 6px 0 0;
    font-size: 14px;
    color: ${p => p.theme.textSecondary};
  }
`;
const Panel = styled.section`
  display: grid;
  gap: 7px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 10px;
  padding: 11px 13px;
  background: ${p => p.theme.surface};
`;
const Sources = styled(Panel)`
  display: flex;
  flex-wrap: wrap;
  gap: 10px 22px;
  select {
    width: 220px;
  }
`;
const TransportPosition = styled.output`
  min-width: 113px;
  padding-right: 7px;
  display: grid;
  gap: 3px;
  font-family: ui-monospace, monospace;
  strong {
    font-size: 18px;
  }
  small {
    font-size: 10px;
    color: ${p => p.theme.textSecondary};
  }
`;
const TimelineTools = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 10px;
  font-size: 13px;
  font-weight: 700;
  div {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }
`;
const Status = styled.div`
  font-size: 12px;
  color: ${p => p.theme.textSecondary};
`;
const Alert = styled.p`
  margin: 0;
  font-size: 13px;
  border-left: 3px solid #d84d67;
  padding: 7px 10px;
`;
const Hint = styled.p`
  margin: 0;
  font-size: 12px;
  color: ${p => p.theme.textSecondary};
`;
