import { STAFF_CLEFS, StaffClef } from './clefs';
import { StaffChord, StaffEvent, getRhythm, getStaffStep } from './notation';

export type ChordStem = {
  x: number;
  startStep: number;
  endStep: number;
  down: boolean;
  flags: number;
};

export const layoutChord = (
  chord: StaffChord,
  bpm: number,
  clef: StaffClef,
) => {
  const middle = getStaffStep(STAFF_CLEFS[clef].middle);
  const steps = chord.notes.map(event => getStaffStep(event.note));
  const down = Math.max(...steps) - middle >= middle - Math.min(...steps);
  const voices: { rhythm: string; notes: StaffEvent[] }[] = [];
  chord.notes.forEach(event => {
    const rhythm =
      event.duration === undefined
        ? 'held'
        : String(getRhythm(event.duration, bpm).beats);
    // Chromatic unisons cannot share a stem without overlapping their heads.
    const voice = voices.find(
      voice =>
        voice.rhythm === rhythm &&
        voice.notes.every(
          n => getStaffStep(n.note) !== getStaffStep(event.note),
        ),
    );
    if (voice) voice.notes.push(event);
    else voices.push({ rhythm, notes: [event] });
  });
  let right = -12;
  const notes: { event: StaffEvent; dotOffset: number; stem?: ChordStem }[] =
    [];
  voices.forEach(voice => {
    const rhythm = getRhythm(voice.notes[0].duration, bpm);
    const ordered = [...voice.notes].sort(
      (a, b) => (down ? -1 : 1) * (getStaffStep(a.note) - getStaffStep(b.note)),
    );
    let previous: StaffEvent | undefined;
    const heads = ordered.map(event => {
      const displaced =
        previous &&
        Math.abs(getStaffStep(previous.note) - getStaffStep(event.note)) ===
          1 &&
        previous.headOffset === 0;
      const separation = rhythm.stem ? 10 : 14;
      const head = {
        ...event,
        headOffset: displaced ? (down ? -separation : separation) : 0,
      };
      previous = head;
      return head;
    });
    const offset = right + 12 - Math.min(...heads.map(n => n.headOffset));
    const headRight = offset + Math.max(...heads.map(n => n.headOffset));
    const voiceSteps = heads.map(n => getStaffStep(n.note));
    const low = Math.min(...voiceSteps);
    const high = Math.max(...voiceSteps);
    const stemLength = 32 + Math.max(0, rhythm.flags - 1) * 6;
    const stem: ChordStem | undefined = rhythm.stem
      ? {
          x: offset + (down ? -5 : 5),
          startStep: down ? high : low,
          endStep: down ? low - stemLength / 5 : high + stemLength / 5,
          down,
          flags: rhythm.flags,
        }
      : undefined;
    const dotOffset = headRight + 11;
    right = Math.max(
      headRight + (rhythm.dotted ? 14 : 7),
      stem && rhythm.flags ? stem.x + 11 : 0,
    );
    heads.forEach((event, index) =>
      notes.push({
        event: { ...event, headOffset: event.headOffset + offset },
        dotOffset,
        stem: index === 0 ? stem : undefined,
      }),
    );
  });
  return { notes, right };
};
