import {
  CSSProperties,
  memo,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import styled from 'styled-components';

import {
  Clip,
  GRID,
  Project,
  Track,
  clipBeats,
  isTrackAudible,
  projectEnd,
  snapBeat,
  trackLabels,
} from 'app/services/ArrangementService/project';
import { getBeatsPerMeasure } from 'app/services/MelodiesService/meter';

interface Props {
  project: Project;
  position: number;
  zoom: number;
  locked: boolean;
  following: boolean;
  trackId?: string;
  clipId?: string;
  onSeek: (beat: number) => void;
  onSelect: (track: Track, clip?: Clip) => void;
  onMove: (track: Track, clip: Clip, beat: number) => void;
  onMix: (track: Track, patch: Partial<Track>) => void;
}

export const ArrangementTimeline = ({
  project,
  position,
  zoom,
  locked,
  following,
  trackId,
  clipId,
  onSeek,
  onSelect,
  onMove,
  onMix,
}: Props) => {
  const container = useRef<HTMLDivElement>(null);
  const ruler = useRef<HTMLDivElement>(null);
  const drag = useRef<{
    id: string;
    x: number;
    beat: number;
    moved: boolean;
  }>();
  const [preview, setPreview] = useState<{ id: string; beat: number }>();
  const measure = getBeatsPerMeasure(project.meter);
  const barWidth = measure * zoom;
  const bars = Math.max(
    8,
    Math.ceil((Math.max(position, projectEnd(project)) + measure) / measure),
  );
  const solo = project.tracks.some(track => track.solo);
  const markers = useMemo(
    () =>
      Array.from({ length: bars }, (_, index) => (
        <button
          key={index}
          type="button"
          aria-label={`Go to bar ${index + 1}`}
          disabled={locked}
          onClick={event => {
            if (event.detail === 0) {
              event.stopPropagation();
              onSeek(index * measure);
            }
          }}
        >
          {String(index + 1).padStart(2, '0')}
        </button>
      )),
    [bars, locked, measure, onSeek],
  );

  useEffect(() => {
    const scroller = container.current;
    const timeline = ruler.current;
    if (!following || !scroller || !timeline) return;
    const bounds = scroller.getBoundingClientRect();
    const left = timeline.getBoundingClientRect().left + position * zoom;
    const inset = timeline.offsetLeft;
    if (left > bounds.right - 28 || left < bounds.left + inset)
      scroller.scrollLeft = Math.max(0, position * zoom - 36);
  }, [following, position, zoom]);

  return (
    <Scroll
      ref={container}
      role="region"
      aria-label="Arrangement timeline"
      tabIndex={0}
    >
      <Grid
        style={
          {
            '--beat': `${zoom}px`,
            '--bar': `${barWidth}px`,
            '--length': `${bars * barWidth}px`,
          } as CSSProperties
        }
      >
        <Corner>
          Tracks <small>{project.tracks.length}</small>
        </Corner>
        <Ruler
          ref={ruler}
          onClick={event => {
            if (!locked)
              onSeek(
                snapBeat(
                  (event.clientX -
                    event.currentTarget.getBoundingClientRect().left) /
                    zoom,
                ),
              );
          }}
        >
          {markers}
        </Ruler>
        {project.tracks.map((track, index) => (
          <Row key={track.id}>
            <TrackHeader $selected={track.id === trackId} $kind={track.kind}>
              <button
                type="button"
                className="track-title"
                aria-pressed={track.id === trackId}
                onClick={() => onSelect(track)}
              >
                <span className="track-index">
                  {String(index + 1).padStart(2, '0')}
                </span>
                <span className="track-name">
                  <strong>{track.name}</strong>
                  <small>{trackLabels[track.kind]}</small>
                </span>
              </button>
              <div className="mix-buttons">
                <button
                  type="button"
                  aria-label={`Mute ${track.name}`}
                  title="Mute"
                  aria-pressed={track.mute}
                  onClick={() => onMix(track, { mute: !track.mute })}
                >
                  M
                </button>
                <button
                  type="button"
                  aria-label={`Solo ${track.name}`}
                  title="Solo"
                  aria-pressed={track.solo}
                  onClick={() => onMix(track, { solo: !track.solo })}
                >
                  S
                </button>
              </div>
            </TrackHeader>
            <Lane
              $odd={index % 2 === 1}
              onClick={event => {
                if (event.target !== event.currentTarget || locked) return;
                onSelect(track);
                onSeek(
                  snapBeat(
                    (event.clientX -
                      event.currentTarget.getBoundingClientRect().left) /
                      zoom,
                  ),
                );
              }}
            >
              {track.clips.map(clip => (
                <ClipButton
                  key={clip.id}
                  type="button"
                  $kind={clip.source.kind}
                  $muted={!isTrackAudible(track, solo)}
                  aria-pressed={clip.id === clipId}
                  title={clip.name}
                  aria-label={`${clip.name}, beat ${Number(
                    (clip.start + 1).toFixed(2),
                  )}`}
                  style={{
                    left:
                      (preview?.id === clip.id ? preview.beat : clip.start) *
                      zoom,
                    width: Math.max(3, clipBeats(clip, project.bpm) * zoom - 2),
                  }}
                  onClick={() => onSelect(track, clip)}
                  onKeyDown={event => {
                    if (
                      locked ||
                      !['ArrowLeft', 'ArrowRight'].includes(event.key)
                    )
                      return;
                    event.preventDefault();
                    onMove(
                      track,
                      clip,
                      Math.max(
                        0,
                        clip.start + (event.key === 'ArrowLeft' ? -GRID : GRID),
                      ),
                    );
                  }}
                  onPointerDown={event => {
                    if (locked || event.button !== 0) return;
                    drag.current = {
                      id: clip.id,
                      x: event.clientX,
                      beat: clip.start,
                      moved: false,
                    };
                    event.currentTarget.setPointerCapture(event.pointerId);
                  }}
                  onPointerMove={event => {
                    const active = drag.current;
                    if (active?.id !== clip.id) return;
                    const delta = event.clientX - active.x;
                    if (Math.abs(delta) < 4 && !active.moved) return;
                    active.moved = true;
                    active.beat = snapBeat(clip.start + delta / zoom);
                    setPreview({ id: clip.id, beat: active.beat });
                  }}
                  onPointerUp={() => {
                    const active = drag.current;
                    drag.current = undefined;
                    setPreview(undefined);
                    if (active?.moved) {
                      onSelect(track, clip);
                      onMove(track, clip, active.beat);
                    }
                  }}
                  onPointerCancel={() => {
                    drag.current = undefined;
                    setPreview(undefined);
                  }}
                >
                  <span>{clip.name}</span>
                  <ClipDrawing clip={clip} />
                </ClipButton>
              ))}
            </Lane>
          </Row>
        ))}
        {!project.tracks.length && (
          <Row>
            <TrackHeader $kind="melody" $selected={false} />
            <EmptyLane>
              Add a melody or beat, or record a voice track.
            </EmptyLane>
          </Row>
        )}
        <Playhead
          style={{ transform: `translateX(${position * zoom}px)` }}
          aria-hidden="true"
        />
      </Grid>
    </Scroll>
  );
};

const ClipDrawing = memo(function ClipDrawing({ clip }: { clip: Clip }) {
  const { source, offset, length } = clip;
  const x = (value: number) => ((value - offset) / length) * 240;
  return (
    <svg viewBox="0 0 240 26" preserveAspectRatio="none" aria-hidden="true">
      {source.kind === 'voice'
        ? source.peaks.map((peak, index) => {
            const start = x(
              ((index + 0.5) / source.peaks.length) * clip.sourceLength,
            );
            return start >= 0 && start < 240 ? (
              <path
                key={index}
                d={`M${start} ${13 - peak * 12}v${Math.max(1, peak * 24)}`}
              />
            ) : null;
          })
        : source.kind === 'drums'
        ? source.hits
            .filter(hit => hit.beat >= offset && hit.beat < offset + length)
            .slice(0, 600)
            .map((hit, index) => (
              <circle
                key={index}
                cx={x(hit.beat) + 2}
                cy={4 + (hit.row % 5) * 4}
                r="2"
              />
            ))
        : source.notes
            .filter(note => note.start < offset + length && note.end > offset)
            .slice(0, 600)
            .map((note, index) => (
              <rect
                key={index}
                x={Math.max(0, x(note.start))}
                y={23 - (note.pitch % 24)}
                width={Math.max(
                  1,
                  Math.min(240, x(note.end)) - Math.max(0, x(note.start)),
                )}
                height="2"
                rx="1"
              />
            ))}
    </svg>
  );
});

const accent = (kind: Track['kind']) =>
  kind === 'voice' ? '#f38c99' : kind === 'drums' ? '#e7b465' : '#71d9c2';

