import { memo } from 'react';

import {
  fretEdges,
  fretWidths,
  guitarFrets,
} from 'app/services/VirtualGuitarService/fretboard';

import { Inlays } from './styles';

export const fretMarkerOptions = [
  { value: 'dots', label: 'Dots' },
  { value: 'none', label: 'No markers' },
  { value: 'trapezoids', label: 'Gibson trapezoids' },
  { value: 'sharktooth', label: 'Ibanez sharktooth' },
  { value: 'vine', label: 'Tree of Life' },
] as const;

export type FretMarkerStyle = typeof fretMarkerOptions[number]['value'];

const vineFrets = [
  [3, 0.75, 'leaf', 1],
  [5, 0.57, 'curl', 1],
  [7, 0.25, 'sprout', -1],
  [9, 0.36, 'curl', -1],
  [12, 0.55, 'leaf', 1],
  [15, 0.66, 'leaf', -1],
  [17, 0.25, 'sprout', 1],
  [19, 0.39, 'leaf', 1],
  [21, 0.7, 'sprout', -1],
  [24, 0.58, 'leaf', 1],
] as const;

export const markedFrets: readonly number[] = vineFrets.map(([fret]) => fret);
const octaveFrets = [12, 24];
const shapeArtwork = {
  trapezoids: (
    <>
      <path fill="#c4d4cb" d="M4 5 28 13V51L4 59Z" />
      <path fill="#eef5eb" opacity=".42" d="m4 5 24 8v8L4 38Z" />
    </>
  ),
  sharktooth: <path fill="#e5eee5" d="M4 3H30L21 22H24L14 40H17L5 61Z" />,
};

const vineAnchors = vineFrets.map(([fret, stemY, shape, lean]) => {
  const width = fretWidths[fret];
  const x = fretEdges[fret] + width / 2;
  const octave = octaveFrets.includes(fret);
  return {
    fret,
    stemX: octave ? x - width * 1.65 : x,
    stemY,
    shape,
    lean,
    x,
    width,
    rows: octave ? [1 / 6, 5 / 6] : [1 / 2],
  };
});

const stemPoints = [
  { x: fretEdges[1], y: 0.47 },
  ...vineAnchors.map(({ stemX, stemY }) => ({ x: stemX, y: stemY })),
  { x: fretEdges[guitarFrets.length], y: 0.47 },
];

const vineStem = [
  `M${stemPoints[0].x} ${stemPoints[0].y}`,
  ...stemPoints.slice(1).map((end, index) => {
    const start = stemPoints[index];
    const before = stemPoints[index - 1] ?? start;
    const after = stemPoints[index + 2] ?? end;
    const step = (end.x - start.x) / 3;
    // The tangent at a joint comes from both neighbouring points.
    const startSlope = (end.y - before.y) / (end.x - before.x);
    const endSlope = (after.y - start.y) / (after.x - start.x);
    return `C${start.x + step} ${start.y + startSlope * step} ${end.x - step} ${
      end.y - endSlope * step
    } ${end.x} ${end.y}`;
  }),
].join(' ');

const vineShapes = {
  leaf: 'M-1 .93C-.59 .4-.85-.2-.35-.49C.14-.78 .56-.55 1-1C.72-.24 .53 .23 .1 .52C-.24 .74-.68 .61-1 .93Z',
  sprout:
    'M-1 .93C-.6 .43-.76-.04-.3-.42C.12-.77 .57-.54 1-1C.86-.37 .65-.01 .27 .05C.04 .09-.2 .06-.36 .21C-.53 .42-.7 .62-1 .93Z',
  curl: 'M-1 .93C-.49 .47 .5 .33 .78-.27C1.02-.78 .59-1 .11-.98C-.45-1.04-.85-.65-.73-.2C-.62 .19-.2 .33 .11 .17C.42 .01 .44-.34 .17-.48C.37-.24 .15 .06-.08 .06C-.4 .06-.58-.19-.53-.47C-.47-.75-.11-.9 .17-.85C.5-.81 .65-.52 .52-.19C.34 .3-.37 .58-1 .93Z',
};

const VineArtwork = ({ lineWidth = 1.25 }: { lineWidth?: number }) => (
  <g fill="#fff">
    <path
      d={vineStem}
      fill="none"
      stroke="#fff"
      strokeWidth={lineWidth}
      vectorEffect="non-scaling-stroke"
    />
    {vineAnchors.map(({ fret, x, stemX, stemY, width, rows, shape, lean }) => (
      <g key={fret}>
        {rows.map(y => {
          const leafWidth = width * 0.37 * lean;
          const leafHeight =
            (rows.length === 2 ? 0.11 : 0.086) * (stemY < y ? -1 : 1);
          const rootX = x - leafWidth;
          const rootY = y + 0.93 * leafHeight;
          const span = rootX - stemX;
          return (
            <g key={y}>
              <path
                d={`M${stemX} ${stemY} C${stemX + span * 0.4} ${stemY} ${
                  rootX - span * 0.22
                } ${rootY + (stemY - rootY) * 0.25} ${rootX} ${rootY}`}
                fill="none"
                stroke="#fff"
                strokeWidth={lineWidth * 0.8}
                vectorEffect="non-scaling-stroke"
              />
              <path
                d={vineShapes[shape]}
                transform={`translate(${x} ${y}) scale(${leafWidth} ${leafHeight})`}
              />
            </g>
          );
        })}
      </g>
    ))}
  </g>
);

export const FretInlays = memo(function FretInlays({
  markers,
  columns,
}: {
  markers: FretMarkerStyle;
  columns: number;
}) {
  return (
    <Inlays aria-hidden="true">
      {markers === 'vine' && (
        <svg
          viewBox={`0 0 ${fretEdges[columns]} 1`}
          preserveAspectRatio="none"
          data-vine
        >
          <VineArtwork />
        </svg>
      )}
      {guitarFrets.slice(0, columns).map(fret => {
        const marked = markedFrets.includes(fret);
        const octave = octaveFrets.includes(fret);
        const firstFret =
          fret === 1 && (markers === 'trapezoids' || markers === 'sharktooth');
        return (
          <span key={fret}>
            {markers === 'dots' && marked && (
              <>
                <i />
                {octave && <i />}
              </>
            )}
            {markers !== 'dots' &&
              markers !== 'none' &&
              markers !== 'vine' &&
              (marked || firstFret) && (
                <svg
                  viewBox="0 0 32 64"
                  preserveAspectRatio="none"
                  data-marker={markers}
                >
                  {shapeArtwork[markers]}
                </svg>
              )}
          </span>
        );
      })}
    </Inlays>
  );
});

export const FretMarkerPreview = ({
  markers,
}: {
  markers: FretMarkerStyle;
}) => (
  <svg viewBox="0 0 48 32" aria-hidden="true" focusable="false">
    <rect width="48" height="32" rx="3" fill="#193339" />
    {markers === 'dots' && (
      <g fill="#fff">
        <circle cx="24" cy="7" r="3" />
        <circle cx="24" cy="25" r="3" />
      </g>
    )}
    {markers === 'vine' && (
      <svg
        viewBox={`${fretEdges[11]} 0 ${fretEdges[14] - fretEdges[11]} 1`}
        preserveAspectRatio="none"
        width="48"
        height="32"
      >
        <VineArtwork lineWidth={0.7} />
      </svg>
    )}
    {markers !== 'dots' && markers !== 'none' && markers !== 'vine' && (
      <svg
        viewBox="0 0 32 64"
        x="17"
        y="4"
        width="14"
        height="24"
        preserveAspectRatio="none"
      >
        {shapeArtwork[markers]}
      </svg>
    )}
    <path d="M16 0V32M32 0V32" stroke="#829996" opacity=".64" />
    <path
      d="M0 4H48M0 9H48M0 14H48M0 18H48M0 23H48M0 28H48"
      stroke="#c4d4cb"
      strokeWidth=".6"
      opacity=".68"
    />
  </svg>
);
