import { useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import { selectEffects } from 'app/services/EffectsService/selectors';
import type { Melody } from 'app/services/MelodiesService/types';
import { downloadBlob, downloadMelody } from 'app/services/MelodyExportService';
import { MelodyExportError } from 'app/services/MelodyExportService/errors';
import type { TabDraft } from 'app/services/TablatureService/tabCreator';
import { tabText } from 'app/services/TablatureService/tabPlayback';

export const TabDownloads = ({
  draft,
  melody,
}: {
  draft: TabDraft;
  melody: Melody;
}) => {
  const { instruments } = useSelector(selectEffects);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const pending = useRef(false);
  const empty = !melody.notes.length;

  const download = async () => {
    if (pending.current) return;
    pending.current = true;
    setBusy(true);
    setError('');
    try {
      await downloadMelody(melody, 'wav', instruments[melody.timbre]);
    } catch (cause) {
      setError(
        cause instanceof MelodyExportError
          ? cause.message
          : 'Could not prepare WAV. Try again.',
      );
    } finally {
      pending.current = false;
      setBusy(false);
    }
  };

  return (
    <>
      <button
        type="button"
        disabled={empty}
        onClick={() =>
          downloadBlob(
            new Blob([tabText(draft)], { type: 'text/plain;charset=utf-8' }),
            'tab-creator.txt',
          )
        }
      >
        Download tabs (.txt)
      </button>
      <button
        type="button"
        disabled={empty || busy}
        onClick={() => void download()}
      >
        {busy ? 'Preparing WAV…' : 'Download WAV'}
      </button>
      {error && <p role="alert">{error}</p>}
    </>
  );
};
