const Arrow = () => <span aria-hidden="true">→</span>;

export const LandingPage = () => {
  const { hash } = useLocation();
  const navigationType = useNavigationType();
  useEffect(() => {
    if (['#features', '#getting-started', '#faq'].includes(hash)) {
      document.getElementById(hash.slice(1))?.scrollIntoView();
    } else if (navigationType === 'PUSH') {
      window.scrollTo(0, 0);
    }
  }, [hash, navigationType]);

  return (
    <>
      <PublicSiteHeader />
      <Content>
        <Hero>
          <div>
            <h1>
              Play music <em>in your browser</em>
            </h1>
            <HeroCopy>
              Try the piano, guitar, or drum machine here. In Melody Studio, you
              can record a melody and see it as sheet music or tabs.
            </HeroCopy>
            <HeroActions>
              <PrimaryLink to={sandbox}>
                Open Melody Studio <Arrow />
              </PrimaryLink>
              <SecondaryLink href="#features">Explore features</SecondaryLink>
            </HeroActions>
            <Inputs>
              You can also connect a MIDI keyboard, guitar, or mic in Melody
              Studio.
            </Inputs>
          </div>
          <LandingInstruments />
        </Hero>

        <Features id="features" aria-labelledby="features-heading">
          <h2 id="features-heading">What you can do</h2>
          {groups.map(({ title, artwork, mirrorArtwork, tools }) => (
            <FeatureGroup key={artwork} aria-labelledby={`feature-${artwork}`}>
              <FeatureCover $mirrored={mirrorArtwork}>
                <img
                  src={`${featureArtworkPath}/${artwork}.webp`}
                  alt=""
                  width={1920}
                  height={640}
                  loading="lazy"
                  decoding="async"
                />
                <FeatureHeading>
                  <h3 id={`feature-${artwork}`}>{title}</h3>
                </FeatureHeading>
              </FeatureCover>
              <ToolList $columns={tools.length}>
                {tools.map(({ title, path, icon, description }) => {
                  const content = (
                    <>
                      <ToolIcon>
                        <HeaderIcon name={icon} />
                      </ToolIcon>
                      {path && <Arrow />}
                      <ToolCopy>
                        <strong>{title}</strong>
                        <span>{description}</span>
                      </ToolCopy>
                    </>
                  );

                  return (
                    <li key={title}>
                      {path ? (
                        <ToolCard as={Link} to={path}>
                          {content}
                        </ToolCard>
                      ) : (
                        <ToolCard>{content}</ToolCard>
                      )}
                    </li>
                  );
                })}
              </ToolList>
            </FeatureGroup>
          ))}
        </Features>

        <LandingSection id="getting-started" aria-labelledby="start-heading">
          <h2 id="start-heading">Getting started</h2>
          <Steps role="list">
            {steps.map(({ title, description, path }, index) => (
              <li key={title}>
                <StepNumber aria-hidden="true">{index + 1}</StepNumber>
                <h3>{path ? <Link to={path}>{title}</Link> : title}</h3>
                <p>{description}</p>
              </li>
            ))}
          </Steps>
        </LandingSection>

        <LandingSection aria-labelledby="benefits-heading">
          <h2 id="benefits-heading">Why play here?</h2>
          <Benefits>
            {benefits.map(({ artwork, title, description }) => (
              <div key={artwork}>
                <BenefitArtwork
                  src={`${benefitArtworkPath}/${artwork}.webp`}
                  alt=""
                  width={900}
                  height={360}
                  loading="lazy"
                  decoding="async"
                />
                <h3>{title}</h3>
                <p>{description}</p>
              </div>
            ))}
          </Benefits>
        </LandingSection>

        <FaqSection id="faq" aria-labelledby="faq-heading">
          <h2 id="faq-heading">Common questions</h2>
          <div>
            {questions.map(({ question, answer }) => (
              <Question key={question}>
                <summary>{question}</summary>
                <p>{answer}</p>
              </Question>
            ))}
          </div>
        </FaqSection>

        <PlayCallout aria-labelledby="play-heading">
          <div>
            <h2 id="play-heading">Play your first melody</h2>
            <p>Pick a sound you like and try a few notes.</p>
          </div>
          <PrimaryLink to={sandbox}>
            Start playing <Arrow />
          </PrimaryLink>
        </PlayCallout>
      </Content>
      <Footer>
        <FooterNavigation aria-label="Footer">
          {footerGroups.map(({ title, links }) => (
            <div key={title}>
              <h2>{title}</h2>
              <ul>
                {links.map(([label, path]) => (
                  <li key={path}>
                    {path.startsWith('#') ? (
                      <a href={path}>{label}</a>
                    ) : (
                      <Link to={path}>{label}</Link>
                    )}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </FooterNavigation>
        <FooterCredit>
          <BrandLogo />
          <span>
            Author:{' '}
            <a
              href="https://polyakovin.ru/"
              target="_blank"
              rel="author noopener noreferrer"
              title="Melody Generator author's website (opens in a new tab)"
            >
              Igor Polyakov
            </a>
          </span>
        </FooterCredit>
      </Footer>
    </>
  );
};

