import { useLayoutEffect, useMemo, useRef, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { batch, useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';

import { formatPitch } from 'app/services/ChordsService';
import { selectEffects } from 'app/services/EffectsService/selectors';
import {
  TIME_SIGNATURES,
  TimeSignature,
} from 'app/services/MelodiesService/meter';
import { MAX_TEMPO, MIN_TEMPO } from 'app/services/MelodiesService/tempo';
import { useLibraryPlayback } from 'app/services/MelodiesService/useLibraryPlayback';
import {
  createMelodyAudioExport,
  downloadBlob,
} from 'app/services/MelodyExportService';
import { MelodyExportError } from 'app/services/MelodyExportService/errors';
import {
  Phrase,
  composePhrase,
} from 'app/services/MelodyGenerationService/compose';
import {
  GenerationSettings,
  MAX_BARS,
  MIN_BARS,
  chordPatterns,
  defaultSettings,
  moods,
  randomAccompaniment,
  randomKey,
  randomMelody,
  randomTiming,
  rhythms,
} from 'app/services/MelodyGenerationService/options';
import {
  encodePhraseMidi,
  phraseFilename,
  phrasePlayback,
  phraseRecordingProject,
} from 'app/services/MelodyGenerationService/output';
import { METRONOME_METERS } from 'app/services/MetronomeService/rhythm';
import { notesActions, selectNotes } from 'app/services/NotesService';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import {
  getScale,
  selectSettings,
  settingsActions,
} from 'app/services/SettingsService';

import { HeaderIcon } from 'app/components/HeaderIcon';
import { getTimbrePresentation } from 'app/components/TimbrePicker/catalog';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

import {
  ActionButton,
  Field,
  FieldPair,
  MelodyGeneratorInstrumentPicker,
  MelodyGeneratorKeyPicker,
  modeLabel,
} from './MelodyGeneratorControls';
import { MelodyGeneratorPreview } from './MelodyGeneratorPreview';
import { MelodyGeneratorScore } from './MelodyGeneratorScore';

const keyLabel = ({ tonic, scale, mode }: Phrase) => {
  const label =
    mode === 'ionian'
      ? 'major'
      : mode === 'aeolian'
      ? 'minor'
      : modeLabel(scale, mode);
  return `${formatPitch(tonic)} ${label}`;
};
const moodChoices = Object.keys(moods).sort();
const formats = ['midi', 'wav', 'mp3'] as const;
type Format = typeof formats[number];

export const MelodyGeneratorPage = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { isRecording, customScale: studioNotes } = useSelector(selectSettings);
  const { instruments } = useSelector(selectEffects);
  const hasComposition = useSelector(state => {
    const { melody, project } = selectNotes(state);
    return !!(melody.notes.length || project);
  });
  const [settings, setSettings] = useState(() => ({
    ...defaultSettings,
    bpm: String(defaultSettings.bpm),
    bars: String(defaultSettings.bars),
    customScale: chromaticNotes.filter(
      note =>
        note === 'C' ||
        (studioNotes ?? getScale('diatonic', 'ionian')).includes(note),
    ),
  }));
  const [phrase, setPhrase] = useState<Phrase>();
  const [exporting, setExporting] = useState<Format>();
  const [exportError, setExportError] = useState<{
    phrase: Phrase;
    message: string;
  }>();
  const playback = useLibraryPlayback({ loop: true });
  const timingHeading = useRef<HTMLHeadingElement>(null);
  const resultHeading = useRef<HTMLHeadingElement>(null);
  const returning = useRef(false);
  const configuration = useMemo(
    () => ({
      ...settings,
      bpm: Number(settings.bpm),
      bars: Number(settings.bars),
      customScale:
        settings.scale === 'custom' ? settings.customScale : undefined,
    }),
    [settings],
  );
  useLayoutEffect(() => {
    const heading = phrase ? resultHeading.current : timingHeading.current;
    if (!heading || (!phrase && !returning.current)) return;
    returning.current = false;
    heading.focus({ preventScroll: true });
    window.scrollTo(0, 0);
  }, [phrase]);

  const meter = METRONOME_METERS[settings.timeSignature];
  const updateSettings = (patch: Partial<typeof settings>) =>
    setSettings(current => ({ ...current, ...patch }));

  const generate = (configuration: GenerationSettings) => {
    const piece = composePhrase(configuration);
    setPhrase(piece);
    void playback.start(phrasePlayback(piece));
  };

  const download = async (piece: Phrase, format: Format) => {
    setExportError(undefined);
    setExporting(format);
    try {
      const filename = phraseFilename(
        piece,
        getTimbrePresentation(piece.timbre).label,
        format,
      );
      const blob =
        format === 'midi'
          ? new Blob([encodePhraseMidi(piece)], { type: 'audio/midi' })
          : await createMelodyAudioExport(
              phrasePlayback(piece),
              format,
              timbre => instruments[timbre],
            );
      downloadBlob(blob, filename);
    } catch (cause) {
      setExportError({
        phrase: piece,
        message:
          cause instanceof MelodyExportError
            ? cause.message
            : 'Could not prepare the file. Try again.',
      });
    } finally {
      setExporting(undefined);
    }
  };

  const openPhrase = (target: 'studio' | 'play-along') => {
    if (!phrase || isRecording) return;
    if (
      hasComposition &&
      !window.confirm('Replace the current composition with this melody?')
    )
      return;
    const project = phraseRecordingProject(phrase);
    playback.stop();
    batch(() => {
      dispatch(notesActions.loadRecordingProject(project));
      dispatch(settingsActions.loadMelodySettings(project.tracks[0].melody));
    });
    if (target === 'studio') navigate('/sandbox/editor');
    else navigate('/play-along/recording');
  };

  return (
    <Page>
      <Helmet>
        <title>Generate a melody</title>
        <meta
          name="description"
          content="Generate a melody in any scale with optional chords, bass and drums. Listen on repeat, open it in Melody Studio or Practice, or download MIDI, WAV or MP3."
        />
      </Helmet>
      <header>
        <h1>Generate a melody</h1>
        {!phrase && (
          <p>Set the pace, choose the notes, and add backing tracks.</p>
        )}
      </header>
      {!phrase ? (
        <Workspace
          onSubmit={event => {
            event.preventDefault();
            generate(configuration);
          }}
        >
          <Settings>
            <Group aria-labelledby="timing-heading">
              <GroupHeading>
                <HeaderIcon name="metronome" />
                <h2 id="timing-heading" ref={timingHeading} tabIndex={-1}>
                  Timing
                </h2>
                <RandomizeButton
                  label="Randomize timing"
                  onClick={() => {
                    const { bpm, bars, timeSignature } = randomTiming();
                    updateSettings({
                      bpm: String(bpm),
                      bars: String(bars),
                      timeSignature,
                    });
                  }}
                />
              </GroupHeading>
              <FieldPair>
                <Field id="tempo" label="Tempo (BPM)" help="How fast it plays">
                  <input
                    id="generator-tempo"
                    aria-describedby="generator-tempo-help"
                    type="number"
                    min={MIN_TEMPO}
                    max={MAX_TEMPO}
                    required
                    value={settings.bpm}
                    onChange={event =>
                      setSettings({ ...settings, bpm: event.target.value })
                    }
                  />
                </Field>
                <Field
                  id="length"
                  label="Length (bars)"
                  help="How many bars the loop lasts"
                >
                  <input
                    id="generator-length"
                    aria-describedby="generator-length-help"
                    type="number"
                    min={MIN_BARS}
                    max={MAX_BARS}
                    required
                    value={settings.bars}
                    onChange={event =>
                      setSettings({ ...settings, bars: event.target.value })
                    }
                  />
                </Field>
              </FieldPair>
              <Field
                id="meter"
                label="Time signature"
                help="How beats fit in a bar"
              >
                <select
                  id="generator-meter"
                  aria-describedby="generator-meter-help"
                  value={settings.timeSignature}
                  onChange={event =>
                    setSettings({
                      ...settings,
                      timeSignature: event.target.value as TimeSignature,
                    })
                  }
                >
                  {TIME_SIGNATURES.map(meter => (
                    <option key={meter}>{meter}</option>
                  ))}
                </select>
              </Field>
              <BeatStrip
                aria-label={`Beat groups: ${meter.groups.join(' + ')}`}
                role="img"
              >
                {meter.groups.map((count, index) => (
                  <div key={index} style={{ flex: count }}>
                    {Array.from({ length: count }, (_, beat) => (
                      <span key={beat} />
                    ))}
                  </div>
                ))}
              </BeatStrip>
            </Group>
            <Group aria-labelledby="key-heading">
              <GroupHeading>
                <HeaderIcon name="chords" />
                <h2 id="key-heading">Key &amp; scale</h2>
                <RandomizeButton
                  label="Randomize key and scale"
                  onClick={() => updateSettings(randomKey())}
                />
              </GroupHeading>
              <MelodyGeneratorKeyPicker
                value={settings}
                timbre={settings.timbre}
                onChange={updateSettings}
              />
            </Group>
            <Group aria-labelledby="melody-heading">
              <GroupHeading>
                <HeaderIcon name="melodies" />
                <h2 id="melody-heading">Melody</h2>
                <RandomizeButton
                  label="Randomize melody settings"
                  onClick={() => updateSettings(randomMelody())}
                />
              </GroupHeading>
              <FieldPair>
                <Field
                  id="rhythm"
                  label="Melody rhythm"
                  help="When notes start and how long they last"
                >
                  <select
                    id="generator-rhythm"
                    aria-describedby="generator-rhythm-help"
                    value={settings.rhythm}
                    onChange={event =>
                      setSettings({
                        ...settings,
                        rhythm: event.target
                          .value as GenerationSettings['rhythm'],
                      })
                    }
                  >
                    {Object.keys(rhythms).map(rhythm => (
                      <option key={rhythm}>{rhythm}</option>
                    ))}
                  </select>
                </Field>
                <Field
                  id="mood"
                  label="Melody mood"
                  help="The shape of the tune and choice of chords"
                >
                  <select
                    id="generator-mood"
                    aria-describedby="generator-mood-help"
                    value={settings.mood}
                    onChange={event =>
                      setSettings({
                        ...settings,
                        mood: event.target.value as GenerationSettings['mood'],
                      })
                    }
                  >
                    {moodChoices.map(mood => (
                      <option key={mood}>{mood}</option>
                    ))}
                  </select>
                </Field>
              </FieldPair>
              <MelodyGeneratorInstrumentPicker
                value={settings.timbre}
                onChange={timbre => updateSettings({ timbre })}
              />
            </Group>
            <Group aria-labelledby="arrangement-heading">
              <GroupHeading>
                <HeaderIcon name="drums" />
                <h2 id="arrangement-heading">Accompaniment</h2>
                <RandomizeButton
                  label="Randomize accompaniment"
                  onClick={() => updateSettings(randomAccompaniment())}
                />
              </GroupHeading>
              <Field
                id="chords"
                label="Chord pattern"
                help="How the chords are played"
              >
                <select
                  id="generator-chords"
                  aria-describedby="generator-chords-help"
                  value={settings.chordPattern}
                  onChange={event =>
                    setSettings({
                      ...settings,
                      chordPattern: event.target
                        .value as GenerationSettings['chordPattern'],
                    })
                  }
                >
                  {Object.entries(chordPatterns).map(([id, label]) => (
                    <option key={id} value={id}>
                      {label}
                    </option>
                  ))}
                </select>
              </Field>
              <CheckOptions>
                <label>
                  <input
                    type="checkbox"
                    checked={settings.bass}
                    onChange={event =>
                      setSettings({ ...settings, bass: event.target.checked })
                    }
                  />
                  <span>
                    Add bass<small>Low notes beneath the melody</small>
                  </span>
                </label>
                <label>
                  <input
                    type="checkbox"
                    checked={settings.drums}
                    onChange={event =>
                      setSettings({ ...settings, drums: event.target.checked })
                    }
                  />
                  <span>
                    Add drums<small>A beat that follows the meter</small>
                  </span>
                </label>
              </CheckOptions>
            </Group>
          </Settings>
          <PreviewPanel>
            <MelodyGeneratorPreview settings={configuration} />
            <GenerateActions>
              <ActionButton type="submit" className="selected">
                <HeaderIcon name="generate-melody" />
                Generate melody
              </ActionButton>
            </GenerateActions>
          </PreviewPanel>
        </Workspace>
      ) : (
        <Panel aria-labelledby="generated-melody">
          <ResultHeading>
            <h2 id="generated-melody" ref={resultHeading} tabIndex={-1}>
              Your melody
            </h2>
            <ActionButton
              type="button"
              onClick={() => {
                playback.stop();
                returning.current = true;
                setPhrase(undefined);
              }}
            >
              <HeaderIcon name="back" />
              Back to settings
            </ActionButton>
          </ResultHeading>
          <p role="status">
            {keyLabel(phrase)} · {phrase.bpm} BPM · {phrase.bars} bars in{' '}
            {phrase.timeSignature}
          </p>
          <p>
            {getTimbrePresentation(phrase.timbre).label} · {phrase.rhythm} ·{' '}
            {phrase.mood}
          </p>
          <p>
            {[
              chordPatterns[phrase.chordPattern],
              phrase.bass && 'Bass',
              phrase.drums && 'Drums',
            ]
              .filter(Boolean)
              .join(' · ')}
          </p>
          <Actions>
            <ActionButton
              type="button"
              onClick={() => void playback.toggle(phrasePlayback(phrase))}
            >
              <HeaderIcon name={playback.activeTitle ? 'stop' : 'play'} />
              {playback.activeTitle ? 'Stop preview' : 'Play preview'}
            </ActionButton>
            <ActionButton
              type="button"
              disabled={isRecording}
              onClick={() => openPhrase('studio')}
            >
              <HeaderIcon name="sandbox" />
              Open in Melody Studio
            </ActionButton>
            <ActionButton
              type="button"
              disabled={isRecording}
              onClick={() => openPhrase('play-along')}
            >
              <HeaderIcon name="play-along" />
              Open in Practice
            </ActionButton>
          </Actions>
          <Actions
            role="group"
            aria-label="Download melody"
            aria-busy={!!exporting}
          >
            {formats.map(format => (
              <ActionButton
                key={format}
                type="button"
                disabled={!!exporting}
                onClick={() => void download(phrase, format)}
              >
                <HeaderIcon name="download" />
                {exporting === format
                  ? `Preparing ${format.toUpperCase()}…`
                  : `Download ${format.toUpperCase()}`}
              </ActionButton>
            ))}
          </Actions>
          {exportError?.phrase === phrase && (
            <ErrorText role="alert">{exportError.message}</ErrorText>
          )}
          {isRecording && <p>Stop recording before opening this melody.</p>}
          {playback.loading && <p role="status">Loading sound…</p>}
          {playback.error && (
            <ErrorText role="alert">{playback.error}</ErrorText>
          )}
          <MelodyGeneratorScore
            phrase={phrase}
            position={playback.position}
            isPlaying={playback.isPlaying}
            onSeek={playback.seek}
          />
          {phrase.accompaniment.length > 0 && (
            <>
              <h3>Chord progression</h3>
              <Progression>
                {phrase.chords.map((chord, bar) => (
                  <li key={bar}>
                    <span>Bar {bar + 1}</span> <strong>{chord}</strong>
                  </li>
                ))}
              </Progression>
            </>
          )}
        </Panel>
      )}
    </Page>
  );
};

const Page = styled(PageWrapper)`
  max-width: none;
  padding-inline: clamp(16px, 3vw, 48px);
  display: grid;
  gap: 20px;

  h1 {
    margin: 0 0 6px;
    text-align: left;
    font-family: inherit;
    font-size: clamp(28px, 4vw, 44px);
    font-weight: 680;
  }

  p {
    margin: 0;
    color: ${p => p.theme.textSecondary};
  }
`;

const Panel = styled.section`
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  min-width: 0;
  gap: 16px;
  padding: clamp(12px, 3vw, 20px);
  border: 1px solid ${p => p.theme.border};
  border-radius: 14px;
  background: ${p => p.theme.surface};

  h2 {
    font-size: 20px;
  }

  h3 {
    font-size: 16px;
    font-weight: 650;
  }
`;

const Workspace = styled.form`
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr);
  align-items: start;
  gap: 16px;

  @media (max-width: 1060px) {
    grid-template-columns: minmax(0, 1fr);
  }
`;

const Settings = styled.div`
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;

  @media (max-width: 660px) {
    grid-template-columns: minmax(0, 1fr);
  }
`;

const Group = styled(Panel)`
  align-content: start;
`;

const GroupHeading = styled.header`
  display: flex;
  align-items: center;
  gap: 10px;

  > svg {
    color: ${p => p.theme.primary};
    flex: none;
  }
`;

const DiceButton = styled.button`
  display: grid;
  flex: 0 0 44px;
  place-items: center;
  height: 44px;
  padding: 0;
  margin-inline-start: auto;
  color: ${p => p.theme.primary};

  &:hover {
    background: ${p => p.theme.backgroundVariant};
  }
`;

const RandomizeButton = ({
  label,
  onClick,
}: {
  label: string;
  onClick: () => void;
}) => (
  <DiceButton type="button" aria-label={label} title={label} onClick={onClick}>
    <HeaderIcon name="dice" />
  </DiceButton>
);

const BeatStrip = styled.div`
  display: flex;
  gap: 6px;

  div {
    display: flex;
    gap: 3px;
  }

  span {
    flex: 1;
    height: 8px;
    border-radius: 2px;
    background: ${p => p.theme.backgroundVariant};
  }

  span:first-child {
    background: ${p => p.theme.primary};
  }
`;

const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
`;

const PreviewPanel = styled(Panel)`
  position: sticky;
  top: calc(var(--app-header-height, 0px) + 16px);

  @media (max-width: 1060px) {
    position: static;
  }
`;

const GenerateActions = styled(Actions)`
  padding-top: 16px;
  border-top: 1px solid ${p => p.theme.border};

  button {
    flex: 1 1 auto;
  }
`;

const CheckOptions = styled.div`
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;

  label {
    display: flex;
    align-items: flex-start;
    gap: 6px;
    padding: 8px;
    border: 1px solid ${p => p.theme.border};
    border-radius: 8px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 650;
  }

  input {
    margin: 4px 0 0;
  }

  small {
    display: block;
    color: ${p => p.theme.textSecondary};
    font-size: 12px;
    line-height: 1.35;
    font-weight: 400;
  }
`;

const ResultHeading = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
`;

const Progression = styled.ol`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(64px, 1fr));
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;

  li {
    display: grid;
    gap: 4px;
    padding: 8px;
    border-radius: 8px;
    background: ${p => p.theme.backgroundVariant};
    overflow-wrap: anywhere;
  }

  span {
    color: ${p => p.theme.textSecondary};
    font-size: 12px;
  }
`;

const ErrorText = styled.p`
  && {
    color: ${p => p.theme.danger};
  }
`;
