import { useState } from 'react';
import styled from 'styled-components';

import type { Melody, NoteInMelody } from 'app/services/MelodiesService/types';
import type { FretPosition } from 'app/services/TablatureService/fingering';
import {
  studioTabBar,
  tabBarAt,
  tabMeter,
  writeStudioTab,
} from 'app/services/TablatureService/studioTab';
import type { TabNote } from 'app/services/TablatureService/tabCreator';
import {
  STRINGS,
  type StringInstrumentType,
} from 'app/services/TablatureService/tuning';

import { type TabFormat, TabGrid } from 'app/components/TabCreator/TabGrid';
import { TabTechniques } from 'app/components/TabCreator/TabTechniques';

type Props = {
  melody: Melody;
  instrument: StringInstrumentType;
  positions: readonly (FretPosition | undefined)[];
  format: TabFormat;
  readOnly: boolean;
  playingAt?: number;
  onChange: (notes: NoteInMelody[]) => void;
};

export const StudioTabEditor = ({
  melody,
  instrument,
  positions,
  format,
  readOnly,
  playingAt,
  onChange,
}: Props) => {
  const [bar, setBar] = useState(0);
  const [selection, setSelection] = useState<{
    id: string;
    tick: number;
    string: number;
  }>();
  const shownBar = playingAt === undefined ? bar : tabBarAt(melody, playingAt);
  const { steps, unmapped } = studioTabBar(
    melody,
    positions,
    instrument,
    shownBar,
    selection?.tick,
  );
  const strings = STRINGS[instrument];
  const stepIndex = Math.max(
    0,
    steps.findIndex(step => step.id === selection?.id),
  );
  const string = selection?.string ?? 0;
  const step = steps[stepIndex];
  const note = step.cells[string]?.note;
  const playingStep =
    playingAt === undefined
      ? undefined
      : steps.reduce(
          (best, step, index) => (step.start <= playingAt ? index : best),
          0,
        );

  const goToBar = (next: number) => {
    if (!Number.isSafeInteger(next * tabMeter(melody).stepsPerBar) || next < 0)
      return;
    setSelection(undefined);
    setBar(next);
  };
  const commit = (
    stepIndex: number,
    string: number,
    fret: number | null,
    technique?: TabNote,
  ) => {
    if (readOnly) return;
    const next = writeStudioTab(
      melody,
      instrument,
      steps[stepIndex],
      string,
      fret,
      technique,
    );
    if (next !== melody.notes) onChange(next);
  };

  return (
    <Editor aria-label="Tab editor" data-studio-tab-editor="">
      <Controls>
        <button
          type="button"
          disabled={shownBar === 0 || readOnly}
          onClick={() => goToBar(bar - 1)}
        >
          Previous bar
        </button>
        <label>
          Bar
          <input
            key={shownBar}
            type="number"
            min="1"
            step="1"
            defaultValue={shownBar + 1}
            disabled={readOnly}
            onKeyDown={event => {
              if (event.key === 'Enter') event.currentTarget.blur();
            }}
            onBlur={event => {
              const input = event.currentTarget;
              const next = input.valueAsNumber - 1;
              input.value = String(shownBar + 1);
              if (next !== bar) goToBar(next);
            }}
          />
        </label>
        <button
          type="button"
          disabled={readOnly}
          onClick={() => goToBar(bar + 1)}
        >
          Next bar
        </button>
      </Controls>
      <p>
        Select a string and step, then type a fret from 0 to 24. Use the arrow
        keys to move between cells.
      </p>
      <TabGrid
        format={format}
        strings={strings}
        steps={steps.map(({ cells }) => cells.map(cell => cell?.note ?? null))}
        stepInfo={steps.map(({ id, start }) => ({
          id,
          title: `${(start / 1000).toFixed(3)} s`,
        }))}
        cursor={{ step: stepIndex, string }}
        playingStep={playingStep}
        readOnly={readOnly}
        onSelect={({ step, string }) => {
          const { id, tick } = steps[step];
          setSelection({ id, tick, string });
        }}
        onFret={({ step, string }, fret) => commit(step, string, fret)}
      />
      {unmapped > 0 && (
        <p>
          Some notes in this bar are outside this tuning’s range. You can edit
          them in the melody editor.
        </p>
      )}
      <Controls>
        <span>
          Step {stepIndex + 1}, string {string + 1} ({strings[string]})
        </span>
        {note && !readOnly ? (
          <>
            <TabTechniques
              note={note}
              onChange={next => commit(stepIndex, string, note.fret, next)}
            />
            <button
              type="button"
              onClick={() => commit(stepIndex, string, null)}
            >
              Clear note
            </button>
          </>
        ) : (
          <span>
            {readOnly
              ? 'Stop playback to edit the tab.'
              : 'Enter a fret to add a technique.'}
          </span>
        )}
      </Controls>
    </Editor>
  );
};

const Editor = styled.section`
  display: grid;
  gap: 8px;
  min-width: 0;
  margin-top: 10px;
  padding: 8px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.surface};
  font-size: 13px;

  p {
    margin: 0;
    color: ${p => p.theme.textSecondary};
  }
`;

const Controls = styled.div`
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 10px;

  label {
    display: flex;
    align-items: center;
    gap: 6px;
  }

  input[type='number'] {
    width: 64px;
  }

  button,
  select,
  input[type='number'] {
    min-height: 32px;
    font-size: inherit;
  }
`;
