import { useEffect, useRef, useState } from 'react';
import styled from 'styled-components';

import { useConnectedGuitarInput } from 'app/services/GuitarInputService/context';
import { RealtimeFrame } from 'app/services/GuitarInputService/polyphonicStream';
import { Note } from 'app/services/NotesService';

import { GuitarTuning } from './GuitarRoll';

export const useGuitarPractice = (
  enabled: boolean,
  onFrame: (frame: RealtimeFrame) => void,
  onUnavailable: () => void,
) => {
  const guitar = useConnectedGuitarInput();
  const [sounding, setSounding] = useState<Note[]>([]);
  const [error, setError] = useState('');
  const [revision, setRevision] = useState(0);
  const [mono, setMono] = useState(
    () => localStorage.getItem('playAlongGuitarPolyphonic') !== 'true',
  );
  const frameRef = useRef(onFrame);
  frameRef.current = onFrame;
  const unavailableRef = useRef(onUnavailable);
  unavailableRef.current = onUnavailable;
  const { connected, subscribeNotes } = guitar;
  useEffect(() => {
    setSounding([]);
    setError('');
    if (!enabled) return;
    frameRef.current({ events: [], soundingNotes: [], noteCount: 0 });
    if (!connected) {
      unavailableRef.current();
      return;
    }
    let active = true;
    const unsubscribe = subscribeNotes(
      frame => {
        if (!active) return;
        frameRef.current(frame);
        setSounding(previous =>
          previous.join(',') === frame.soundingNotes.join(',')
            ? previous
            : frame.soundingNotes,
        );
      },
      () => {
        if (!active) return;
        setError(
          'The app stopped recognizing notes. Retry or switch to single-note mode.',
        );
        setSounding([]);
        unavailableRef.current();
      },
      mono,
    );
    return () => {
      active = false;
      unsubscribe();
    };
  }, [connected, enabled, mono, revision, subscribeNotes]);
  return {
    guitar,
    sounding,
    error,
    mono,
    available: connected && !error,
    retry: () => setRevision(value => value + 1),
    setMono: (value: boolean) => {
      setMono(value);
      localStorage.setItem('playAlongGuitarPolyphonic', String(!value));
    },
  };
};

export const GuitarPracticeInput = ({
  input,
  tuning,
  onTuning,
  locked,
}: {
  input: ReturnType<typeof useGuitarPractice>;
  tuning: GuitarTuning;
  onTuning?: (tuning: GuitarTuning) => void;
  locked: boolean;
}) => {
  const { guitar } = input;
  return (
    <Panel aria-label="Guitar practice input">
      <Controls>
        <label>
          Audio input{' '}
          <select
            aria-label="Guitar audio input"
            value={guitar.deviceId}
            disabled={locked || guitar.connecting}
            onChange={event => guitar.selectDevice(event.target.value)}
          >
            <option value="">System microphone / audio interface</option>
            {guitar.devices.map(device => (
              <option key={device.deviceId} value={device.deviceId}>
                {device.label || 'Audio input'}
              </option>
            ))}
          </select>
        </label>
        {guitar.channels > 1 && (
          <label>
            Channel{' '}
            <select
              aria-label="Guitar channel"
              value={guitar.channel}
              disabled={locked}
              onChange={event =>
                guitar.selectChannel(Number(event.target.value))
              }
            >
              {Array.from({ length: guitar.channels }, (_, index) => (
                <option key={index} value={index}>
                  {index + 1}
                </option>
              ))}
            </select>
          </label>
        )}
        <button
          type="button"
          disabled={!guitar.supported || guitar.connecting}
          onClick={() =>
            guitar.connected ? guitar.disconnect() : guitar.connect()
          }
        >
          {guitar.connecting
            ? 'Connecting…'
            : guitar.connected
            ? 'Disconnect guitar'
            : 'Connect guitar'}
        </button>
        {guitar.monitoring && (
          <button type="button" onClick={guitar.stopMonitoring}>
            Turn off live sound
          </button>
        )}
        {onTuning && (
          <label>
            Tuning{' '}
            <select
              aria-label="Guitar tuning"
              value={tuning}
              disabled={locked}
              onChange={event => onTuning(event.target.value as GuitarTuning)}
            >
              <option value="guitar">Standard E A D G B E</option>
              <option value="guitarDropD">Drop D: D A D G B E</option>
            </select>
          </label>
        )}
        <label>
          Recognition{' '}
          <select
            aria-label="Guitar recognition"
            disabled={locked}
            value={input.mono ? 'mono' : 'poly'}
            onChange={event => input.setMono(event.target.value === 'mono')}
          >
            <option value="mono">Single note: faster</option>
            <option value="poly">Notes and chords</option>
          </select>
        </label>
        <span aria-label="Guitar level">
          Level{' '}
          <meter
            min={0}
            max={1}
            value={guitar.level.peak}
            aria-label="Guitar signal"
          />
        </span>
      </Controls>
      <details>
        <summary>How to play guitar</summary>
        <p>
          Connect your guitar through an audio interface or play into a
          microphone. The app checks pitch on your device without recording. Any
          string works if it produces the target pitch. To play chords, choose
          Notes and chords. Wear headphones to keep the guide out of the
          microphone. If recognition feels slow, use Wait mode or increase the
          timing tolerance.
        </p>
      </details>
      {!guitar.supported && (
        <p role="alert">This browser does not support audio input.</p>
      )}
      {guitar.connectionStatus && (
        <p role="status">{guitar.connectionStatus}</p>
      )}
      {guitar.error && <p role="alert">{guitar.error}</p>}
      {input.error && (
        <p role="alert">
          {input.error} <button onClick={input.retry}>Retry recognition</button>
        </p>
      )}
    </Panel>
  );
};

const Panel = styled.section`
  border: 1px solid ${p => p.theme.border};
  border-radius: 10px;
  padding: 10px 12px;
  font-size: 12px;
  details {
    margin-top: 8px;
  }
  summary {
    cursor: pointer;
    color: ${p => p.theme.textSecondary};
  }
  p {
    margin: 8px 0 0;
    color: ${p => p.theme.textSecondary};
  }
`;
const Controls = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 14px;
  label {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 4px;
    min-width: 0;
  }
  select {
    max-width: 100%;
    min-width: 0;
  }
`;
