import { useId, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';

import { scaleLabels } from 'app/services/MelodiesService/scaleOptimization';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import type { JustNote, Octave } from 'app/services/NotesService/types';
import {
  Mode,
  Scale,
  ScaleSelection,
  scales,
  selectSettings,
  settingsActions,
} from 'app/services/SettingsService';
import {
  isMicrotonalScale,
  microtonalInstrument,
  microtonalPreset,
  tuningLabel,
} from 'app/services/SettingsService/microtonal';
import {
  getScalePreview,
  pitchForTonic,
  tonicForPitch,
} from 'app/services/SettingsService/scalePreview';
import type { SettingsState } from 'app/services/SettingsService/slice/types';
import { useScalePreview } from 'app/services/SettingsService/useScalePreview';

const modeLabels: Partial<Record<Mode, string>> = {
  ionian: 'Ionian (major)',
  dorian: 'Dorian',
  phrygian: 'Phrygian',
  lydian: 'Lydian',
  mixolydian: 'Mixolydian',
  aeolian: 'Aeolian (minor)',
  locrian: 'Locrian',
  h1: 'Harmonic minor',
  j1: 'Melodic minor',
  p1: 'Major pentatonic',
  p5: 'Minor pentatonic',
  pb1: 'Major blues',
  pb5: 'Minor blues',
};

const labelForMode = (scale: Scale, mode: Mode) =>
  microtonalPreset(scale, mode)?.label ??
  modeLabels[mode] ??
  (scales[scale].modes.length === 1
    ? scaleLabels[scale]
    : `Mode ${(scales[scale].modes as readonly Mode[]).indexOf(mode) + 1}`);

const displayNote = (note: JustNote) => note.replace('#', '♯');
const whiteNotes = chromaticNotes.filter(note => !note.includes('#'));
const studioOctaves: Octave[] = [1, 2, 3, 4];

export const scaleSelectionLabel = ({
  scale,
  mode,
  pitch,
}: Omit<ScaleSelection, 'octave'>) =>
  [
    displayNote(tonicForPitch(pitch)),
    ...Array.from(new Set([scaleLabels[scale], labelForMode(scale, mode)])),
  ].join(' · ');

export const ScalePicker = () => {
  const dispatch = useDispatch();
  const settings = useSelector(selectSettings);
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const dismiss = () => {
    setOpen(false);
    trigger.current?.focus();
  };

  return (
    <>
      <Trigger
        ref={trigger}
        type="button"
        aria-haspopup="dialog"
        onClick={() => setOpen(true)}
      >
        <span>Scale:</span> {scaleSelectionLabel(settings)}
        <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true">
          <path
            d="m3 4.5 3 3 3-3"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
          />
        </svg>
      </Trigger>
      {open && (
        <ScaleDialog
          settings={settings}
          onApply={selection => {
            dispatch(settingsActions.setScaleSelection(selection));
            dismiss();
          }}
          onDismiss={dismiss}
        />
      )}
    </>
  );
};

type DialogElement = HTMLDialogElement & { showModal(): void; close(): void };

export const ScaleDialog = ({
  settings,
  onApply,
  onDismiss,
  onboarding = false,
  availableScales,
  editableCustomScale = false,
  pitchForRoot = pitchForTonic,
}: {
  settings: Pick<
    SettingsState,
    keyof ScaleSelection | 'timbre' | 'customScale'
  >;
  onApply: (selection: ScaleSelection & { customScale?: JustNote[] }) => void;
  onDismiss: () => void;
  onboarding?: boolean;
  availableScales?: readonly Scale[];
  editableCustomScale?: boolean;
  pitchForRoot?: (root: JustNote, pitch: number) => number;
}) => {
  const id = useId();
  const dialog = useRef<DialogElement>(null);
  const [selection, setSelection] = useState(() => ({
    scale: settings.scale,
    mode: settings.mode,
    pitch: settings.pitch,
    octave: settings.octave,
    customScale: settings.customScale,
  }));
  const { scale, mode, pitch, octave } = selection;
  const tonic = tonicForPitch(pitch);
  const notes = useMemo(
    () => getScalePreview(selection, selection.customScale),
    [selection],
  );
  const { play, stop, activeKey, isPlaying, failed } = useScalePreview();
  const scaleOptions =
    availableScales ??
    (Object.keys(scales) as Scale[]).filter(
      value =>
        (!onboarding || (value !== 'chromatic' && value !== 'elevenTone')) &&
        (value !== 'custom' || settings.customScale?.length) &&
        (!isMicrotonalScale(value) ||
          microtonalInstrument(settings.timbre)?.scale === value ||
          value === settings.scale),
    );
  const modes: readonly Mode[] = scales[scale].modes;
  const octaves = Array.from(new Set([...studioOctaves, settings.octave])).sort(
    (a, b) => a - b,
  );

  useLayoutEffect(() => {
    const element = dialog.current!;
    element.showModal();
    return () => {
      if (element.hasAttribute('open')) element.close();
    };
  }, []);

  useLayoutEffect(() => {
    void play(notes);
  }, [notes, play]);

  const close = () => {
    stop();
    dialog.current?.close();
  };
  const dismiss = () => {
    close();
    onDismiss();
  };
  return createPortal(
    <Dialog
      ref={dialog}
      aria-labelledby={`${id}-title`}
      onCancel={event => {
        event.preventDefault();
        dismiss();
      }}
    >
      <h2 id={`${id}-title`}>Choose a scale</h2>
      <Choices
        title="Root note"
        name={`${id}-tonic`}
        options={chromaticNotes}
        selected={tonic}
        label={displayNote}
        onSelect={key =>
          setSelection({ ...selection, pitch: pitchForRoot(key, pitch) })
        }
        chromatic
      />
      <Choices
        title="Scale family"
        name={`${id}-scale`}
        options={scaleOptions}
        selected={scale}
        label={value =>
          value === 'custom' && editableCustomScale
            ? 'Custom'
            : scaleLabels[value]
        }
        onSelect={value => {
          const nextModes: readonly Mode[] = scales[value].modes;
          setSelection({
            ...selection,
            scale: value,
            mode: nextModes.includes(mode) ? mode : nextModes[0],
          });
        }}
      />
      {modes.length > 1 && (
        <Choices
          title="Mode"
          name={`${id}-mode`}
          options={modes}
          selected={mode}
          label={value => labelForMode(scale, value)}
          onSelect={value => setSelection({ ...selection, mode: value })}
        />
      )}
      {editableCustomScale && scale === 'custom' && (
        <Fieldset>
          <legend>Scale notes</legend>
          <Options $chromatic>
            {chromaticNotes.map((note, index) => (
              <Option key={note}>
                <input
                  type="checkbox"
                  checked={!!selection.customScale?.includes(note)}
                  disabled={index === 0}
                  onChange={({ target }) =>
                    setSelection({
                      ...selection,
                      customScale: chromaticNotes.filter(candidate =>
                        candidate === note
                          ? target.checked
                          : selection.customScale?.includes(candidate),
                      ),
                    })
                  }
                />
                <span>
                  {displayNote(
                    chromaticNotes[
                      (chromaticNotes.indexOf(tonic) + index) % 12
                    ],
                  )}
                </span>
              </Option>
            ))}
          </Options>
        </Fieldset>
      )}
      <Choices
        title="Octave"
        name={`${id}-octave`}
        options={octaves}
        selected={octave}
        label={value => String(value + 1)}
        onSelect={value => setSelection({ ...selection, octave: value })}
      />
      <Figure>
        <figcaption>Piano preview</figcaption>
        <Keyboard
          role="img"
          aria-label={`Notes in the scale: ${notes
            .map(({ key, note, cents }) =>
              [note, key === tonic && 'root', cents && tuningLabel(cents)]
                .filter(Boolean)
                .join(' '),
            )
            .join(', ')}`}
        >
          {chromaticNotes.map(key => {
            const sharp = key.includes('#');
            const degree = notes.find(note => note.key === key);
            const isRoot = key === tonic && !!degree;
            return (
              <PianoKey
                key={key}
                aria-hidden="true"
                data-scale-key={key}
                data-in-scale={!!degree}
                data-playing={activeKey === key}
                $sharp={sharp}
                style={
                  sharp
                    ? {
                        left: `${
                          ((whiteNotes.indexOf(key[0] as JustNote) + 1) / 7) *
                          100
                        }%`,
                      }
                    : undefined
                }
              >
                {isRoot && <RootMark />}
                {displayNote(key)}
                {!!degree?.cents && <small>{tuningLabel(degree.cents)}</small>}
              </PianoKey>
            );
          })}
        </Keyboard>
      </Figure>
      <Actions>
        <button
          type="button"
          onClick={() => (isPlaying ? stop() : void play(notes))}
        >
          {isPlaying ? 'Stop preview' : 'Play preview'}
        </button>
        <div>
          {!onboarding && (
            <button type="button" onClick={dismiss}>
              Cancel
            </button>
          )}
          <Apply
            type="button"
            onClick={() => {
              close();
              onApply(selection);
            }}
          >
            Apply
          </Apply>
        </div>
      </Actions>
      {failed && (
        <ErrorMessage role="status">
          Could not play the piano preview. Try again.
        </ErrorMessage>
      )}
    </Dialog>,
    document.body,
  );
};

const Choices = <Value extends string | number>({
  title,
  name,
  options,
  selected,
  label,
  onSelect,
  chromatic = false,
}: {
  title: string;
  name: string;
  options: readonly Value[];
  selected: Value;
  label: (value: Value) => string;
  onSelect: (value: Value) => void;
  chromatic?: boolean;
}) => (
  <Fieldset>
    <legend>{title}</legend>
    <Options $chromatic={chromatic}>
      {options.map(value => (
        <Option key={value}>
          <input
            type="radio"
            name={name}
            value={value}
            checked={value === selected}
            onChange={() => onSelect(value)}
          />
          <span>{label(value)}</span>
        </Option>
      ))}
    </Options>
  </Fieldset>
);

