const audio = new (window.AudioContext || (window as any).webkitAudioContext)();
const outputContext = audio as AudioContext & {
  setSinkId?: (id: string) => Promise<void>;
};
export const canSelectAudioOutput = () =>
  typeof outputContext.setSinkId === 'function';
export const setAudioOutputDevice = (id: string): Promise<void> =>
  outputContext.setSinkId
    ? outputContext.setSinkId(id)
    : Promise.reject(new Error('Output selection unavailable'));
export const getInstrumentAudioContext = () => audio;
export const isInstrumentAudioRunning = () => audio.state === 'running';
// Call from the initiating gesture before awaiting sample loading.
export const resumeAudio = () =>
  audio.state === 'suspended' ? audio.resume() : Promise.resolve();
let instrumentEffects = loadEffects();
const effectsRacks = new Map<string, EffectsRack>();
export const updateInstrumentEffects = (settings: EffectsByTimbre) => {
  instrumentEffects = settings;
  effectsRacks.forEach((rack, timbre) =>
    rack.update(settings[timbre] ?? defaultEffects(timbre)),
  );
};
const getInstrumentInput = (timbre: string) => {
  let rack = effectsRacks.get(timbre);
  if (!rack) {
    rack = createEffectsRack(
      audio,
      audio.destination,
      instrumentEffects[timbre] ?? defaultEffects(timbre),
      { cursorKey: timbre },
    );
    effectsRacks.set(timbre, rack);
  }
  return rack.input;
};

const loadedSounds = new Map<string, AudioBuffer>();
const pendingSounds = new Map<string, Promise<void>>();
export const loadSound = async (timbre: Timbre) => {
  const { file } = sampleDefinition(timbre);
  if (loadedSounds.has(file)) return;
  const pending = pendingSounds.get(file);
  if (pending) return pending;
  const loading = (async () => {
    const response = await axios.get(
      `${process.env.PUBLIC_URL || ''}/samples/library/${file}`,
      { responseType: 'arraybuffer' },
    );
    loadedSounds.set(file, await audio.decodeAudioData(response.data));
  })();
  pendingSounds.set(file, loading);
  try {
    await loading;
  } finally {
    pendingSounds.delete(file);
  }
};
const bufferFor = (timbre: Timbre) =>
  loadedSounds.get(sampleDefinition(timbre).file);

// Sequencer voices reuse the decoded library buffer without changing live notes.
export const prepareInstrumentSample = async (timbre: Timbre) => {
  await loadSound(timbre);
  return bufferFor(timbre)!;
};

// Independent sequencer voices share the audio clock, sample and effects rack.
export const prepareDrumKit = async () => {
  await loadSound('drums');
  return {
    audio,
    buffer: bufferFor('drums')!,
    destination: getInstrumentInput('drums'),
  };
};
type SampleVoice = {
  key: string;
  source: AudioBufferSourceNode;
  filter: BiquadFilterNode;
  envelope: GainNode;
  release: number;
  note?: Note;
  pitchBendCents: number;
  tuningCents: number;
  harmonic: boolean;
  timbre: Timbre;
  drone: boolean;
  gain: number;
  gainAt?: (time: number) => number;
};
const activeSounds = new Map<string, SampleVoice>();
const voiceKey = (timbre: Timbre, offset: number, rate: number, id?: string) =>
  `${timbre}:${id ?? `${offset}:${rate}`}`;
const noteToTone = (note: Note) => {
  const [name, octave] = splitNote(note);
  return tone[name][octave];
};
const getVoiceExpression = (voice: SampleVoice) => ({
  detune:
    voice.tuningCents +
    voice.pitchBendCents +
    (voice.harmonic && voice.note ? 1200 : 0),
  cutoff:
    voice.harmonic && voice.note
      ? noteToTone(voice.note) * 3
      : audio.sampleRate / 2,
});
const updateVoiceExpression = (voice: SampleVoice, immediate = false) => {
  const { detune, cutoff } = getVoiceExpression(voice);
  voice.source.detune.cancelScheduledValues(audio.currentTime);
  voice.filter.frequency.cancelScheduledValues(audio.currentTime);
  if (immediate) {
    voice.source.detune.setValueAtTime(detune, audio.currentTime);
    voice.filter.frequency.setValueAtTime(cutoff, audio.currentTime);
  } else {
    voice.source.detune.setTargetAtTime(detune, audio.currentTime, 0.01);
    voice.filter.frequency.setTargetAtTime(cutoff, audio.currentTime, 0.01);
  }
};
export const activateHarmonics = (played?: { timbre: Timbre; note: Note }) =>
  activeSounds.forEach(voice => {
    if (
      voice.note &&
      !voice.harmonic &&
      (!played ||
        (voice.timbre === played.timbre && voice.note === played.note))
    ) {
      voice.harmonic = true;
      updateVoiceExpression(voice, true);
    }
  });
export const MAX_PITCH_BEND_CENTS = 100;
export const setNotesPitchBend = (notes: Note[], cents: number) => {
  const detune = Math.max(
    -MAX_PITCH_BEND_CENTS,
    Math.min(MAX_PITCH_BEND_CENTS, cents),
  );
  activeSounds.forEach(voice => {
    if (voice.note && notes.includes(voice.note)) {
      voice.pitchBendCents = detune;
      updateVoiceExpression(voice);
    }
  });
};

export const playSound = (
  timbre: Timbre,
  offset: number,
  playbackRate: number,
  duration = 4,
  note?: Note,
  loop?: SustainLoop | null,
  id?: string,
  gain = 1,
  drone = false,
  tuningCents = 0,
  destination?: AudioNode,
  release = sampleDefinition(timbre).release,
) => {
  const buffer = bufferFor(timbre);
  const key = voiceKey(timbre, offset, playbackRate, id);
  if (
    !buffer ||
    activeSounds.has(key) ||
    !Number.isFinite(offset) ||
    !Number.isFinite(duration) ||
    !Number.isFinite(playbackRate) ||
    playbackRate <= 0 ||
    offset < 0 ||
    duration <= 0 ||
    offset + duration > buffer.duration
  )
    return;
  const source = audio.createBufferSource();
  source.buffer = buffer;
  source.playbackRate.value = playbackRate;
  const filter = audio.createBiquadFilter();
  filter.type = 'lowpass';
  filter.Q.value = Math.SQRT1_2;
  const envelope = audio.createGain();
  envelope.gain.value = gain;
  const voice: SampleVoice = {
    key,
    source,
    filter,
    envelope,
    release,
    note,
    pitchBendCents: 0,
    tuningCents,
    harmonic: false,
    timbre,
    drone,
    gain,
  };
  const { detune, cutoff } = getVoiceExpression(voice);
  source.detune.value = detune;
  filter.frequency.value = cutoff;
  source.connect(filter);
  filter.connect(envelope);
  envelope.connect(destination ?? getInstrumentInput(timbre));
  const sustained =
    loop &&
    loop.loopStart >= 0 &&
    loop.loopStart < loop.loopEnd &&
    loop.loopEnd < duration;
  if (sustained) {
    source.loop = true;
    source.loopStart = offset + loop.loopStart;
    source.loopEnd = offset + loop.loopEnd;
  }
  source.onended = () => {
    if (activeSounds.get(key) === voice) activeSounds.delete(key);
    source.disconnect();
    filter.disconnect();
    envelope.disconnect();
    if (!drone) syncDrones(timbre);
  };
  activeSounds.set(key, voice);
  if (sustained) source.start(audio.currentTime, offset);
  else source.start(audio.currentTime, offset, duration);
  return voice;
};
const releaseVoice = (voice: SampleVoice) => {
  if (activeSounds.get(voice.key) !== voice) return;
  // Detach immediately so a release tail never blocks the next attack.
  activeSounds.delete(voice.key);
  const time = audio.currentTime;
  voice.envelope.gain.cancelScheduledValues(time);
  voice.envelope.gain.setValueAtTime(voice.gainAt?.(time) ?? voice.gain, time);
  voice.envelope.gain.linearRampToValueAtTime(0, time + voice.release);
  voice.source.stop(time + voice.release);
};
const muteSound = (
  timbre: Timbre,
  offset: number,
  rate: number,
  id?: string,
) => {
  const voice = activeSounds.get(voiceKey(timbre, offset, rate, id));
  if (voice) releaseVoice(voice);
};

interface DroneGroup {
  voices: SampleVoice[];
  timer?: number;
  releasing: boolean;
}
const droneGroups = new Map<Timbre, DroneGroup>();

function syncDrones(timbre: Timbre) {
  const definition = sampleDefinition(timbre);
  if (!definition.drones?.length) return;
  const held = Array.from(activeSounds.values()).some(
    voice => voice.timbre === timbre && !voice.drone,
  );
  let group = droneGroups.get(timbre);
  if (held) {
    if (group) {
      if (group.timer !== undefined) window.clearTimeout(group.timer);
      group.timer = undefined;
      if (group.releasing)
        group.voices.forEach(voice => {
          const gain = voice.envelope.gain;
          const current = gain.value;
          gain.cancelScheduledValues(audio.currentTime);
          gain.setValueAtTime(current, audio.currentTime);
          gain.linearRampToValueAtTime(voice.gain, audio.currentTime + 0.015);
        });
      group.releasing = false;
      return;
    }
    const voices = definition.drones
      .map((drone, index) =>
        playSound(
          timbre,
          drone.offset,
          1,
          drone.duration,
          undefined,
          drone,
          `drone:${index}`,
          drone.gain,
          true,
        ),
      )
      .filter((voice): voice is SampleVoice => !!voice);
    if (voices.length) droneGroups.set(timbre, { voices, releasing: false });
    return;
  }
  if (!group || group.timer !== undefined) return;
  const released = group;
  released.timer = window.setTimeout(() => {
    released.releasing = true;
    released.voices.forEach(voice => {
      voice.envelope.gain.cancelScheduledValues(audio.currentTime);
      voice.envelope.gain.setValueAtTime(voice.gain, audio.currentTime);
      voice.envelope.gain.linearRampToValueAtTime(
        0,
        audio.currentTime + definition.release,
      );
    });
    // Keep stop cancellable during a fast reattack; a scheduled source.stop cannot be undone.
    released.timer = window.setTimeout(() => {
      released.voices.forEach(voice => {
        if (activeSounds.get(voice.key) === voice)
          activeSounds.delete(voice.key);
        voice.source.stop();
      });
      droneGroups.delete(timbre);
    }, definition.release * 1000 + 20);
  }, DRONE_GRACE_MS);
}

export const playMp3Note = (
  timbre: Timbre,
  note: Note,
  voiceId = note as string,
  tuningCents = 0,
  destination?: AudioNode,
) => {
  const region = sampleRegion(noteIndex(note), sampleDefinition(timbre));
  if (!region) return;
  const voice = playSound(
    timbre,
    region.offset,
    region.playbackRate,
    region.duration,
    region.expressive ? note : undefined,
    region.loop,
    voiceId,
    1,
    false,
    region.expressive ? tuningCents : 0,
    destination,
  );
  syncDrones(timbre);
  return voice;
};
export const muteMp3Note = (
  note: Note,
  timbre: Timbre = 'studioResonantPiano',
) => {
  const region = sampleRegion(noteIndex(note), sampleDefinition(timbre));
  if (!region) return;
  muteSound(timbre, region.offset, region.playbackRate, note);
  syncDrones(timbre);
};
let expressionVoiceId = 0;
const controlLiveExpressiveVoice = (voice: SampleVoice) => {
  // These gestures belong to this voice alone, even when the keyboard
  // or another string is playing the same pitch.
  voice.note = undefined;
  return {
    setPitchOffset: (
      cents: number,
      transition: 'smooth' | 'step' = 'smooth',
    ) => {
      if (activeSounds.get(voice.key) !== voice || !Number.isFinite(cents))
        return;
      voice.pitchBendCents = cents;
      updateVoiceExpression(voice, transition === 'step');
    },
    stop: () => {
      releaseVoice(voice);
      syncDrones(voice.timbre);
    },
  };
};

export const playLiveExpressiveNote = (
  timbre: Timbre,
  note: Note,
  destination?: AudioNode,
) => {
  const voice = playMp3Note(
    timbre,
    note,
    `expression:${++expressionVoiceId}`,
    0,
    destination,
  );
  if (!voice?.note) {
    if (voice) releaseVoice(voice);
    return;
  }
  return controlLiveExpressiveVoice(voice);
};

const virtualGuitarTimbre = 'distortedGuitar';
let virtualGuitarInput: AudioNode | undefined;
export const loadVirtualGuitar = (timbre: Timbre = virtualGuitarTimbre) =>
  loadSound(timbre);
export const createVirtualGuitarEffects = (
  settings: Parameters<typeof createEffectsRack>[2],
) => createEffectsRack(audio, audio.destination, settings);

export const playVirtualGuitarNote = (
  note: Note,
  timbre: Timbre = virtualGuitarTimbre,
  destination?: AudioNode,
) => {
  if (!bufferFor(timbre)) return;
  const { offset, playbackRate, duration } = melodicSlot(note);
  // The home-page demo still uses its original overdrive.
  destination ??= virtualGuitarInput ??= createGuitarDistortion(audio);
  // Play through the recorded decay instead of repeating a short sustain loop.
  const voice = playSound(
    timbre,
    offset,
    playbackRate,
    duration,
    note,
    undefined,
    `expression:${++expressionVoiceId}`,
    1,
    false,
    0,
    destination,
    0.18,
  );
  if (!voice) return;
  const decayStart = audio.currentTime + 0.16;
  const decayTime = 1.2;
  voice.envelope.gain.setTargetAtTime(0, decayStart, decayTime);
  voice.gainAt = time => Math.exp(-Math.max(0, time - decayStart) / decayTime);
  const { source } = voice;
  const { setPitchOffset, stop } = controlLiveExpressiveVoice(voice);
  return {
    // Playback rate steps between frets while detune keeps smoothing the bend.
    setSlideOffset: (semitones: number) =>
      source.playbackRate.setValueAtTime(
        playbackRate * 2 ** (semitones / 12),
        audio.currentTime,
      ),
    setBend: (cents: number) => setPitchOffset(cents),
    stop,
  };
};

/** A private sample voice keeps simultaneous unisons and live gestures independent. */
export const playExpressiveNote = (
  timbre: Timbre,
  note: Note,
  duration: number,
  expression: NoteExpression,
) => {
  const region = sampleRegion(noteIndex(note), sampleDefinition(timbre));
  if (!region || timbre === 'drums') return () => {};
  const id = `expression:${++expressionVoiceId}`;
  const voice = playMp3Note(timbre, note, id);
  if (voice && !sampleDefinition(timbre).pitchedNotes) {
    voice.note = undefined;
    scheduleExpression(
      voice.source.detune,
      expression,
      audio.currentTime,
      duration / 1000,
    );
  }
  return () => {
    muteSound(timbre, region.offset, region.playbackRate, id);
    syncDrones(timbre);
  };
};
export const playMp3Sound = (note: Note) => {
  const slot = drumSlot(noteIndex(note), bufferFor('drums')?.duration ?? 0);
  if (slot) playSound('drums', slot.offset, 1, slot.duration);
};
export const muteMp3Sound = (note: Note) => {
  const slot = drumSlot(noteIndex(note), bufferFor('drums')?.duration ?? 0);
  if (slot) muteSound('drums', slot.offset, 1);
};
export const playNote = (timbre: Timbre, note: Note, tuningCents = 0) => {
  if (!noteToTone(note)) return;
  if (timbre === 'drums') playMp3Sound(note);
  else playMp3Note(timbre, note, note, tuningCents);
};
export const muteNote = (timbre: Timbre, note: Note) => {
  if (!noteToTone(note)) return;
  if (timbre === 'drums') muteMp3Sound(note);
  else muteMp3Note(note, timbre);
};
