import styled from 'styled-components';

import {
  InstrumentEffects,
  LIVE_INPUT_EFFECTS_KEY,
  effectDefinitions,
  maxEffectsVolume,
  mixerEffectNames,
} from 'app/services/EffectsService/settings';

import { EffectPresets } from './EffectPresets';

export const LiveInputEffects = ({
  settings,
  onChange,
}: {
  settings: InstrumentEffects;
  onChange: (settings: InstrumentEffects) => void;
}) => (
  <Controls>
    <EffectPresets settings={settings} onChange={onChange} />
    <label>
      Output volume: {settings.volume}%
      <input
        type="range"
        aria-label="Live output volume"
        min={0}
        max={maxEffectsVolume(LIVE_INPUT_EFFECTS_KEY)}
        step={1}
        value={settings.volume}
        onChange={event =>
          onChange({ ...settings, volume: Number(event.target.value) })
        }
      />
    </label>
    <details>
      <summary>Configure input effects</summary>
      <Bypass>
        <input
          type="checkbox"
          checked={settings.bypass}
          onChange={event =>
            onChange({ ...settings, bypass: event.target.checked })
          }
        />
        Bypass input effects
      </Bypass>
      <Pedals>
        {mixerEffectNames.map(name => {
          const definition = effectDefinitions[name];
          const effect = settings[name];
          const update = (key: string, value: number | boolean) =>
            onChange({ ...settings, [name]: { ...effect, [key]: value } });
          return (
            <fieldset key={name}>
              <legend>
                <Bypass>
                  <input
                    type="checkbox"
                    checked={effect.enabled}
                    onChange={event => update('enabled', event.target.checked)}
                  />
                  {definition.title}
                </Bypass>
              </legend>
              {name === 'compressor' && (
                <p>
                  Adds about 6 ms of latency. Leave off for the lowest latency.
                </p>
              )}
              {definition.controls.map(control => (
                <label key={control.key}>
                  {control.label}:{' '}
                  {(effect as unknown as Record<string, number>)[control.key]}{' '}
                  {control.unit}
                  <input
                    type="range"
                    aria-label={`Input: ${control.label}`}
                    min={control.min}
                    max={control.max}
                    step={control.step}
                    disabled={!effect.enabled || settings.bypass}
                    value={
                      (effect as unknown as Record<string, number>)[control.key]
                    }
                    onChange={event =>
                      update(control.key, Number(event.target.value))
                    }
                  />
                </label>
              ))}
            </fieldset>
          );
        })}
      </Pedals>
    </details>
  </Controls>
);

const Controls = styled.div`
  margin: 16px 0;
  padding: 12px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  label {
    margin-top: 10px;
  }
  input[type='range'] {
    width: 100%;
  }
  summary {
    margin-top: 12px;
    cursor: pointer;
  }
`;
const Bypass = styled.label`
  display: inline-flex !important;
  flex-direction: row !important;
  align-items: center;
  gap: 6px;
`;
const Pedals = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(230px, 100%), 1fr));
  gap: 12px;
  margin-top: 12px;
  fieldset {
    min-width: 0;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
  }
`;
