const formControls =
  'input, select, textarea, form, fieldset, [form], dialog, [role="dialog"][aria-modal="true"], [role="textbox"], [role="combobox"], [role="listbox"], [role="spinbutton"], [role="slider"]';

export const isFormInputTarget = (target: EventTarget | null): boolean =>
  (target instanceof Element && !!target.closest(formControls)) ||
  (target instanceof HTMLElement && target.isContentEditable);
