import { capitalize } from 'utils';

const modeLabels: Partial<Record<Mode, string>> = {
  ionian: 'Major (Ionian)',
  aeolian: 'Minor (Aeolian)',
  h1: 'Harmonic minor',
  j1: 'Melodic minor',
  p1: 'Major pentatonic',
  p5: 'Minor pentatonic',
  solo: '11 degrees',
  custom: 'Custom',
};

export const modeLabel = (scale: Scale, mode: Mode) =>
  microtonalPreset(scale, mode)?.label ?? modeLabels[mode] ?? capitalize(mode);

