import { useState } from 'react';
import styled from 'styled-components';

export const Controls = styled.div`
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 8px;
  min-width: 0;
  label {
    display: grid;
    gap: 4px;
    font-size: 12px;
    color: ${p => p.theme.textSecondary};
    min-width: 0;
    max-width: 100%;
  }
  input:not([type='checkbox']),
  select {
    min-height: 36px;
    min-width: 0;
    max-width: 100%;
    border: 1px solid ${p => p.theme.border};
    border-radius: 6px;
    padding: 4px 8px;
    background: ${p => p.theme.background};
    color: ${p => p.theme.text};
  }
  input[type='number'] {
    width: 86px;
  }
  input[type='text'] {
    width: 200px;
  }
`;

const submitOnEnter = (event: React.KeyboardEvent<HTMLInputElement>) => {
  if (event.key === 'Enter') event.currentTarget.blur();
};

export const NumberField = ({
  label,
  value,
  disabled,
  min,
  max,
  onCommit,
}: {
  label: string;
  value: number;
  disabled?: boolean;
  min: number;
  max?: number;
  onCommit: (value: number) => void;
}) => {
  const [draft, setDraft] = useState<string>();
  return (
    <label>
      {label}
      <input
        type="number"
        inputMode="decimal"
        min={min}
        max={max}
        step="any"
        disabled={disabled}
        value={draft ?? Number(value.toFixed(3))}
        onChange={event => setDraft(event.target.value)}
        onBlur={event => {
          const next = event.currentTarget.valueAsNumber;
          if (draft !== undefined && Number.isFinite(next))
            onCommit(Math.max(min, Math.min(max ?? Infinity, next)));
          setDraft(undefined);
        }}
        onKeyDown={submitOnEnter}
      />
    </label>
  );
};

export const NameField = ({
  label,
  value,
  disabled,
  onCommit,
}: {
  label: string;
  value: string;
  disabled?: boolean;
  onCommit: (name: string) => void;
}) => {
  const [draft, setDraft] = useState<string>();
  return (
    <label>
      {label}
      <input
        type="text"
        maxLength={120}
        disabled={disabled}
        value={draft ?? value}
        onChange={event => setDraft(event.target.value)}
        onBlur={() => {
          if (draft?.trim() && draft.trim() !== value) onCommit(draft.trim());
          setDraft(undefined);
        }}
        onKeyDown={submitOnEnter}
      />
    </label>
  );
};
