import type { Project } from './project';

const databaseName = 'qwertophone.sequencer.v1';
const activeKey = 'qwertophone.sequencer.active';
const storeName = 'projects';
let database: Promise<IDBDatabase> | undefined;

const openDatabase = () => {
  if (!database) {
    database = new Promise<IDBDatabase>((resolve, reject) => {
      const request = indexedDB.open(databaseName, 1);
      request.onupgradeneeded = () =>
        request.result.createObjectStore(storeName, { keyPath: 'id' });
      request.onsuccess = () => {
        const db = request.result;
        db.onversionchange = () => {
          db.close();
          database = undefined;
        };
        resolve(db);
      };
      request.onerror = () => reject(request.error);
    }).catch(error => {
      database = undefined;
      throw error;
    });
  }
  return database;
};

const transact = async <T>(
  mode: IDBTransactionMode,
  request: (store: IDBObjectStore) => IDBRequest<T>,
): Promise<T> => {
  const db = await openDatabase();
  return new Promise<T>((resolve, reject) => {
    const transaction = db.transaction(storeName, mode);
    const result = request(transaction.objectStore(storeName));
    transaction.oncomplete = () => resolve(result.result);
    transaction.onabort = () => reject(transaction.error);
  });
};

export const readProjects = (): Promise<Project[]> =>
  transact('readonly', store => store.getAll());
export const writeProject = (project: Project) =>
  transact('readwrite', store => store.put(project));
export const deleteProject = (id: string) =>
  transact('readwrite', store => store.delete(id));

export const readActiveProject = () => {
  try {
    return localStorage.getItem(activeKey);
  } catch {
    return null;
  }
};
export const rememberProject = (id: string) => {
  try {
    localStorage.setItem(activeKey, id);
  } catch {
    // The project itself is stored in IndexedDB.
  }
};
