import { splitNote } from 'app/services/NotesService/noteUtils';
import { JustNote, Note } from 'app/services/NotesService/types';

import { SampleDefinition, SustainLoop } from './types';

export const MELODIC_SLOT_SECONDS = 4;
export const DRUM_FIRST = 35;
export const DRUM_LAST = 81;
export const DRONE_GRACE_MS = 35;

export interface SampleRegion {
  offset: number;
  duration: number;
  playbackRate: number;
  expressive: boolean;
  loop?: SustainLoop | null;
}
const semitones: JustNote[] = [
  'C',
  'C#',
  'D',
  'D#',
  'E',
  'F',
  'F#',
  'G',
  'G#',
  'A',
  'A#',
  'B',
];
export const noteIndex = (note: Note) => {
  const [name, octave] = splitNote(note);
  return octave * 12 + semitones.indexOf(name);
};
// Slots are half-open: [offset, offset + duration). The next attack is excluded.
export const melodicSlot = (note: Note) => {
  return melodicSlotForIndex(noteIndex(note));
};
export const melodicSlotForIndex = (index: number) => {
  const root = Math.max(12, Math.min(92, Math.floor(index / 4) * 4));
  return {
    slot: (root - 12) / 4,
    offset: ((root - 12) / 4) * MELODIC_SLOT_SECONDS,
    duration: MELODIC_SLOT_SECONDS,
    playbackRate: 2 ** ((index - root) / 12),
  };
};
export const drumSlot = (index: number, bufferDuration: number) => {
  if (!Number.isInteger(index) || index < DRUM_FIRST || index > DRUM_LAST)
    return undefined;
  const boundaries = [
    [0.5, 0],
    [0.5, 36],
    [1, 45],
    [2, 61],
  ];
  const offset = boundaries.reduce(
    (sum, [length, boundary]) => sum + Math.max(0, index - boundary) * length,
    0,
  );
  const duration = boundaries.reduce(
    (sum, [length, boundary]) => sum + (index >= boundary ? length : 0),
    0,
  );
  if (!Number.isFinite(bufferDuration) || offset + duration > bufferDuration)
    return undefined;
  return { offset, duration };
};

export const sampleRegion = (
  index: number,
  definition: SampleDefinition,
  drums = false,
  bufferDuration = 143,
): SampleRegion | undefined => {
  if (!Number.isInteger(index) || index < 0 || index > 107) return undefined;
  if (drums) {
    const slot = drumSlot(index, bufferDuration);
    return slot && { ...slot, playbackRate: 1, expressive: false };
  }
  if (definition.pitchedNotes) {
    const slot = definition.pitchedNotes.find(note => note.index === index);
    if (!slot || slot.offset + slot.duration > bufferDuration) return undefined;
    return { ...slot, playbackRate: 1, expressive: false };
  }
  if (definition.articulations) {
    const length = definition.articulations.length;
    if (!length) return undefined;
    const relative = index - (definition.articulationBase ?? 36);
    const slot =
      definition.articulations[((relative % length) + length) % length];
    return { ...slot, playbackRate: 1, expressive: false };
  }
  const slot = melodicSlotForIndex(index);
  return { ...slot, loop: definition.slots[slot.slot], expressive: true };
};

// Times are milliseconds. Include the release-transition grace in each span.
export const droneSpans = (notes: { start: number; end: number }[]) => {
  const spans: { start: number; end: number }[] = [];
  [...notes]
    .sort((a, b) => a.start - b.start)
    .forEach(note => {
      const end = note.end + DRONE_GRACE_MS;
      const previous = spans[spans.length - 1];
      if (previous && note.start <= previous.end)
        previous.end = Math.max(previous.end, end);
      else spans.push({ start: note.start, end });
    });
  return spans;
};
