import { nanoid } from '@reduxjs/toolkit';

import type { DrumBeat } from 'app/services/DrumMachineService/beatLibrary';
import { tracksWithHits } from 'app/services/DrumMachineService/patterns';
import type { DrumSample } from 'app/services/DrumMachineService/samples';
import {
  EffectsByTimbre,
  InstrumentEffects,
  normalizeEffects,
} from 'app/services/EffectsService/settings';
import { cropExpression } from 'app/services/MelodiesService/expression';
import {
  TimeSignature,
  getBeatsPerMeasure,
} from 'app/services/MelodiesService/meter';
import type { Melody } from 'app/services/MelodiesService/types';
import { getMelodyBpm } from 'app/services/MelodiesService/useCurrentMelody';
import {
  ExportNote,
  getExportNotes,
} from 'app/services/MelodyExportService/notes';
import type { Timbre } from 'app/services/SynthesizerService/types';

export const MAX_PROJECT_SECONDS = 300;
export const GRID = 0.25;

export type ClipSource =
  | {
      kind: 'melody';
      timbre: Timbre;
      notes: ExportNote[]; // Start and end in quarter notes in this model.
      effects: InstrumentEffects;
    }
  | {
      kind: 'drums';
      hits: { beat: number; row: number; sample: DrumSample }[];
      effects: InstrumentEffects;
      volume: number;
    }
  | { kind: 'voice'; audio: Blob; peaks: number[] };

export type TrackKind = ClipSource['kind'];
export const trackLabels: Record<TrackKind, string> = {
  melody: 'Melody',
  drums: 'Beat',
  voice: 'Voice',
};

export interface Clip {
  id: string;
  name: string;
  start: number; // Quarter notes on the project timeline.
  offset: number; // Source quarters, or seconds for voice.
  length: number;
  sourceLength: number;
  source: ClipSource;
}

export interface Track {
  id: string;
  name: string;
  kind: TrackKind;
  clips: Clip[];
  gain: number;
  pan: number;
  mute: boolean;
  solo: boolean;
}

export interface Project {
  id: string;
  name: string;
  bpm: number;
  meter: TimeSignature;
  tracks: Track[];
}

export const newProject = (
  bpm = 90,
  meter: TimeSignature = '4/4',
): Project => ({
  id: nanoid(),
  name: 'Untitled project',
  bpm,
  meter,
  tracks: [],
});

export const newTrack = (
  kind: TrackKind,
  name: string,
  clips: Clip[] = [],
): Track => ({
  id: nanoid(),
  kind,
  name,
  clips,
  gain: 1,
  pan: 0,
  mute: false,
  solo: false,
});

export const newClip = (
  name: string,
  start: number,
  length: number,
  source: ClipSource,
): Clip => ({
  id: nanoid(),
  name,
  start,
  offset: 0,
  length,
  sourceLength: length,
  source,
});

export const cloneTrack = (track: Track): Track => ({
  ...track,
  id: nanoid(),
  name: `${track.name} copy`,
  solo: false,
  clips: track.clips.map(clip => ({ ...clip, id: nanoid() })),
});

export const snapBeat = (beat: number) =>
  Math.max(0, Math.round(beat / GRID) * GRID);
export const secondsPerBeat = (bpm: number) => 60 / bpm;
export const clipBeats = (clip: Clip, bpm: number) =>
  clip.source.kind === 'voice'
    ? clip.length / secondsPerBeat(bpm)
    : clip.length;
export const projectEnd = ({ tracks, bpm }: Project) =>
  tracks.reduce(
    (last, track) =>
      track.clips.reduce(
        (end, clip) => Math.max(end, clip.start + clipBeats(clip, bpm)),
        last,
      ),
    0,
  );
export const projectFits = (project: Project) =>
  projectEnd(project) <= MAX_PROJECT_SECONDS / secondsPerBeat(project.bpm);
export const isTrackAudible = (track: Track, hasSolo: boolean) =>
  !track.mute && (!hasSolo || track.solo);

export const melodyTrack = (
  name: string,
  melody: Melody,
  start: number,
  effects: EffectsByTimbre,
  live = false,
): Track | undefined => {
  if (!melody.notes.length) return;
  const unit = getMelodyBpm(melody) / 60000;
  const notes = getExportNotes(melody).map(note => ({
    ...note,
    start: note.start * unit,
    end: note.end * unit,
  }));
  const timbre = melody.timbre;
  const settings = normalizeEffects(
    timbre,
    (live ? effects[timbre] : melody.effectPreset?.settings) ?? effects[timbre],
  );
  const end = notes.reduce((last, note) => Math.max(last, note.end), 0);
  return newTrack('melody', name, [
    newClip(name, start, end, {
      kind: 'melody',
      timbre,
      notes,
      effects: settings,
    }),
  ]);
};

export const beatTrack = (
  name: string,
  beat: DrumBeat,
  start: number,
  repeats: number,
) => {
  const bar = getBeatsPerMeasure(beat.timeSignature);
  const steps = bar * 4;
  const hits = tracksWithHits(beat.state, steps).flatMap((id, row) =>
    beat.state.pattern[id]
      .slice(0, steps)
      .flatMap((hit, step) =>
        hit ? [{ beat: step / 4, row, sample: beat.state.samples[id] }] : [],
      ),
  );
  if (!hits.length) return;
  const source: ClipSource = {
    kind: 'drums',
    hits: Array.from({ length: repeats }, (_, index) =>
      hits.map(hit => ({ ...hit, beat: hit.beat + index * bar })),
    ).flat(),
    effects: beat.effects,
    volume: beat.state.volume,
  };
  return newTrack('drums', name, [newClip(name, start, repeats * bar, source)]);
};

// Intersect the clip with the transport's half-open range. Drum hits exactly
// at sourceStart play; hits at sourceEnd belong to the next range.
export const clipWindow = (
  clip: Clip,
  bpm: number,
  from: number,
  to: number,
) => {
  const start = Math.max(from, clip.start);
  const end = Math.min(to, clip.start + clipBeats(clip, bpm));
  if (start >= end) return;
  const unit = clip.source.kind === 'voice' ? secondsPerBeat(bpm) : 1;
  return {
    start,
    end,
    sourceStart: clip.offset + (start - clip.start) * unit,
    sourceEnd:
      end >= clip.start + clipBeats(clip, bpm)
        ? clip.offset + clip.length
        : clip.offset + (end - clip.start) * unit,
  };
};

export const clipNotes = (notes: ExportNote[], from: number, to: number) =>
  notes.flatMap(note => {
    const start = Math.max(from, note.start);
    const end = Math.min(to, note.end);
    if (start >= end) return [];
    const duration = note.end - note.start;
    return [
      {
        ...note,
        start,
        end,
        expression:
          start === note.start && end === note.end
            ? note.expression
            : cropExpression(
                note.expression,
                (start - note.start) / duration,
                (end - note.start) / duration,
              ),
      },
    ];
  });
