import { createSelector } from '@reduxjs/toolkit';

import { RootState } from 'app/services/types';

import { initialState } from '.';
import { recordingProject } from '../project';

const selectSlice = (state: RootState) => state.notes || initialState;

export const selectNotes = createSelector([selectSlice], state => state);

export const selectCompletedRecording = (state: RootState) =>
  state.settings?.isRecording ? undefined : selectSlice(state).melody;

export const selectHasRecordedNotes = (state: RootState) =>
  selectSlice(state).melody.notes.length > 0;

export const selectRecordingProject = createSelector(
  [selectSlice],
  recordingProject,
);

export const selectSoundingNotes = createSelector(
  [selectSlice],
  state => state.soundingNotes,
);

export const selectHasNonPointerNotes = createSelector([selectSlice], state =>
  state.soundingNotes.some(
    note =>
      state.noteInputs[note]?.sources.some(
        source => !source.startsWith('pointer:'),
      ) ?? true,
  ),
);
