import { useCallback, useEffect, useRef, useState } from 'react';

import { createSampleRecording } from 'app/services/DrumMachineService/recording';
import { getBeatsPerMeasure } from 'app/services/MelodiesService/meter';
import { getInstrumentAudioContext } from 'app/services/SynthesizerService';

import { decodeVoice, mixTail, preparePlayback, waveformPeaks } from './audio';
import {
  Clip,
  MAX_PROJECT_SECONDS,
  Project,
  newClip,
  projectEnd,
  secondsPerBeat,
} from './project';

type Phase =
  | 'idle'
  | 'loading'
  | 'playing'
  | 'arming'
  | 'recording'
  | 'finishing';
const lead = 0.035;
type Mixer = ReturnType<Awaited<ReturnType<typeof preparePlayback>>>;

export const useTransport = (
  project: Project,
  reportError: (message: string) => void,
) => {
  const [phase, setPhase] = useState<Phase>('idle');
  const [position, setPosition] = useState(0);
  const [loop, setLoop] = useState(false);
  const cursor = useRef(0);
  const session = useRef<{
    version: number;
    frame?: number;
    timer?: ReturnType<typeof setInterval>;
    recording?: ReturnType<typeof createSampleRecording>;
    mix?: Mixer;
  }>({ version: 0 }).current;

  const seek = useCallback((beat: number) => {
    cursor.current = beat;
    setPosition(beat);
  }, []);

  const disconnect = () => {
    if (session.frame !== undefined) cancelAnimationFrame(session.frame);
    clearInterval(session.timer);
    session.mix?.dispose();
    session.mix = undefined;
  };

  useEffect(
    () => () => {
      session.version++;
      session.recording?.cancel();
      if (session.frame !== undefined) cancelAnimationFrame(session.frame);
      clearInterval(session.timer);
      session.mix?.dispose();
    },
    [session],
  );

  const cancel = () => {
    session.version++;
    session.recording?.cancel();
    session.recording = undefined;
    disconnect();
    setPhase('idle');
  };

  const start = async (onTake?: (clip: Clip) => void) => {
    const end = projectEnd(project);
    const repeating = loop && !onTake;
    const bar = getBeatsPerMeasure(project.meter);
    const loopEnd = Math.ceil(end / bar) * bar;
    const limit = repeating ? loopEnd : end;
    const startBeat = !onTake && cursor.current >= limit ? 0 : cursor.current;
    if (!onTake && !end) return;
    const unit = secondsPerBeat(project.bpm);
    const available = MAX_PROJECT_SECONDS - startBeat * unit;
    if (onTake && available < 0.1) {
      reportError(
        'Move the playhead earlier to record. Projects can be up to 5 minutes long.',
      );
      return;
    }
    reportError('');
    const version = ++session.version;
    setPhase(onTake ? 'arming' : 'loading');
    const fail = (error: unknown) => {
      if (version !== session.version) return;
      cancel();
      reportError(
        error instanceof Error
          ? error.message
          : 'Could not start audio. Try again.',
      );
    };
    try {
      const create = await preparePlayback(project);
      if (version !== session.version) return;
      const audio = getInstrumentAudioContext();
      const begin = () => {
        const mix = create();
        session.mix = mix;
        const at = audio.currentTime + lead;
        const firstEnd = at + Math.max(0, limit - startBeat) * unit;
        const tail = !onTake && !repeating ? mixTail(project) : 0;
        mix.schedule(startBeat, end, at);
        if (repeating) {
          let next = firstEnd;
          const span = loopEnd * unit;
          const scheduleLoop = () => {
            while (next < audio.currentTime + 0.15) {
              // If a suspended tab wakes up late, catch up without scheduling
              // missed passes of the arrangement into the current render.
              if (next < audio.currentTime) {
                const passed = Math.floor((audio.currentTime - next) / span);
                next += passed * span;
                const beat = (audio.currentTime - next) / unit;
                mix.schedule(beat, end, audio.currentTime);
              } else {
                mix.schedule(0, end, next);
              }
              next += span;
            }
          };
          scheduleLoop();
          session.timer = setInterval(scheduleLoop, 50);
        }
        seek(startBeat);
        const update = () => {
          const now = audio.currentTime;
          if (!onTake && !repeating && now >= firstEnd + tail) {
            seek(end);
            cancel();
            return;
          }
          const next = startBeat + Math.max(0, now - at) / unit;
          seek(
            onTake ? next : repeating ? next % loopEnd : Math.min(end, next),
          );
          session.frame = requestAnimationFrame(update);
        };
        session.frame = requestAnimationFrame(update);
        setPhase(onTake ? 'recording' : 'playing');
      };
      if (!onTake) {
        begin();
        return;
      }
      session.recording = createSampleRecording({
        maxSeconds: available + lead,
        audio: {
          echoCancellation: true,
          noiseSuppression: false,
          autoGainControl: false,
        },
        onReady: begin,
        onError: fail,
        onComplete: async blob => {
          if (version !== session.version) return;
          disconnect();
          setPhase('finishing');
          try {
            const buffer = await decodeVoice(blob);
            if (version !== session.version) return;
            const offset = Math.min(lead, buffer.duration / 2);
            const length = Math.min(available, buffer.duration - offset);
            const clip = newClip('Voice take', startBeat, buffer.duration, {
              kind: 'voice',
              audio: blob,
              peaks: waveformPeaks(buffer),
            });
            onTake({ ...clip, offset, length });
            seek(startBeat);
            session.recording = undefined;
            setPhase('idle');
          } catch {
            fail(
              new Error('Could not read the microphone recording. Try again.'),
            );
          }
        },
      });
      await session.recording.start();
    } catch (error) {
      fail(error);
    }
  };

  return {
    phase,
    position,
    loop,
    setLoop,
    seek,
    play: () => start(),
    pause: cancel,
    record: start,
    stop() {
      if (phase === 'recording') {
        setPhase('finishing');
        session.recording?.stop();
        disconnect();
        return;
      }
      cancel();
      seek(0);
    },
    updateMix(next: Project) {
      session.mix?.setMix(next);
    },
  };
};
