import styled from 'styled-components';

import { MAX_FRET } from 'app/services/TablatureService/fingering';
import type { TabNote } from 'app/services/TablatureService/tabCreator';

const frets = Array.from({ length: MAX_FRET + 1 }, (_, fret) => fret);

export const TabTechniques = ({
  note,
  onChange,
}: {
  note: TabNote;
  onChange: (note: TabNote) => void;
}) => (
  <>
    <label>
      Technique
      <select
        value={note.slide !== undefined ? 'slide' : note.bend ? 'bend' : ''}
        onChange={event => {
          const value = event.target.value;
          onChange({
            ...note,
            slide:
              value === 'slide'
                ? note.fret === MAX_FRET
                  ? note.fret - 1
                  : note.fret + 1
                : undefined,
            bend: value === 'bend' ? 2 : undefined,
          });
        }}
      >
        <option value="">None</option>
        <option value="slide">Slide</option>
        <option value="bend">Bend</option>
      </select>
    </label>
    {note.slide !== undefined && (
      <label>
        Slide to fret
        <select
          value={note.slide}
          onChange={event =>
            onChange({ ...note, slide: Number(event.target.value) })
          }
        >
          {frets
            .filter(fret => fret !== note.fret)
            .map(fret => (
              <option key={fret} value={fret}>
                {fret}
              </option>
            ))}
        </select>
      </label>
    )}
    {note.bend !== undefined && (
      <label>
        Bend amount
        <select
          value={note.bend}
          onChange={event =>
            onChange({ ...note, bend: Number(event.target.value) })
          }
        >
          <option value={1}>½ step</option>
          <option value={2}>Whole step</option>
          <option value={3}>1½ steps</option>
        </select>
      </label>
    )}
    <Check>
      <input
        type="checkbox"
        checked={!!note.vibrato}
        onChange={event => onChange({ ...note, vibrato: event.target.checked })}
      />
      Vibrato
    </Check>
  </>
);

const Check = styled.label`
  && {
    display: flex;
    align-items: center;
    gap: 6px;
    min-height: 40px;
    padding: 0 4px;
  }
`;
